var e=[{id:`scen-gerda`,title:`Tante Gerdas Trinkwasser-Panik`,subtitle:`Angst, Verschwörungsglaube & Mitfühlende Empathie (H.1.6)`,character:`Tante Gerda`,avatar:`👵`,context:`Deine Tante Gerda ruft dich völlig aufgelöst an. Sie hat ein Video auf Telegram gesehen und ist überzeugt, dass die Regierung heimlich Chemikalien ins Leitungswasser mischt.`,goal:`Verhindere eine Eskalation, beruhige ihre Panik durch mitfühlende Empathie (H.1.6) und leite das Gespräch auf überprüfbare Realitäten um.`,bereich:`Familie`,laenge:`mittel`,ton:`ernst`,bestehenAb:4,lektion:`Wer Angst hat, hört keine Argumente, sondern Tonfall. Erst wenn Gerda sich ernst genommen fühlt, kann sie selbst nachdenken, und eine gemeinsame Detektivfrage öffnet mehr Türen als die fertige Erklärung. Am Ende zählt, dass die Beziehung heil bleibt und Gerda nicht allein mit dem Video zurückbleibt.`,toolRef:`H.1.6 Die Empathie-Matrix; H.2.1 Die Deeskalations-Matrix; H.2.2 Street Epistemology; H.2.4 Die Ausstiegs-Strategie`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Tante Gerda`,speech:`„Kindchen! Trink bloß kein Wasser mehr aus dem Hahn! Ich habe gerade ein Video gesehen – sie mischen giftige Nanopartikel hinein, um uns willenlos zu machen! Ich habe solche Angst, was machen wir denn jetzt?!“`,options:[{text:`„Tante Gerda, jetzt mal ehrlich: Das ist Unsinn aus dem Internet. Wasserwerke werden ständig kontrolliert, und willenlos macht uns da gar nichts. Wie kann man nur auf so etwas hereinfallen?“`,style:`frontal`,reaction:`„Du hältst mich also für blöd?! Die da oben lachen über Leute wie dich, die blind alles schlucken! Ich wollte dich nur warnen!“`,feedback:`Frontalangriff! Die Sachaussage mag stimmen, aber Gerda hört: „Du bist dumm.“ Sie fühlt sich gedemütigt und klammert sich noch fester an den Mythos.`,score:-2,nextStepId:`step-fail`},{text:`„Oh Gott, Tante Gerda, wirklich?! Ich habe vorhin noch ein Glas getrunken! Müssen wir jetzt ins Krankenhaus? Ich google sofort, was das für Nanopartikel sind!“`,style:`affektiv`,reaction:`„Siehst du! Ich wusste es! Wir müssen sofort Kanister im Supermarkt kaufen und Vorräte anlegen!“`,feedback:`Affektiver Kollaps! Du übernimmst ihre Panik und verstärkst die Hysterie, statt ein Anker der Ruhe zu sein.`,score:-1,nextStepId:`step-panic`},{text:`„Tante Gerda, atme einmal tief durch. Ich höre, wie sehr dich das erschreckt hat, und ich bin ganz bei dir. Erzähl mir in Ruhe: Was genau hast du in dem Video gesehen?“`,style:`deeskalierend`,reaction:`„*atmet hörbar aus* Danke, Liebes... Mein Herz klopft wie verrückt. Es war ein Video von einem Mann im weißen Kittel, der ein Glas Wasser braun gefärbt hat...“`,feedback:`Exzellent! Mitfühlende Empathie (H.1.6): Das Gefühl wird ernst genommen („Ich höre deine Angst“), der Inhalt („Wasser ist giftig“) aber nicht bestätigt. Die emotionale Temperatur sinkt sofort.`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Tante Gerda`,speech:`„Er hat so ein Testgerät ins Wasser gehalten, und das Wasser wurde ganz braun und schlammig! Er sagte, das sind die Toxine, die die Stadtwerke verheimlichen!“`,options:[{text:`„Das ist simple Elektrolyse, Gerda: Die Eisenstäbe rosten im Stromfluss und färben das Wasser braun. Ein uralter Trick von Leuten, die teure Filter verkaufen wollen. Nichts Geheimnisvolles also, glaub mir.“`,style:`frontal`,reaction:`„Glaubst du im Ernst, ein Mann im Kittel würde lügen? Du verteidigst ja schon wieder die Regierung!“`,feedback:`Faktisch korrekt, aber pädagogisch zu schnell. Du lieferst die Lösung als Belehrung, statt Gerda selbst entdecken zu lassen.`,score:0,nextStepId:`step-3-struggle`},{text:`„Das sah bestimmt unheimlich aus. Lass uns knobeln, woraus das Testgerät bestand: Wenn da Eisenstäbe drin waren, die unter Strom rosten, könnte das Braune dann nicht vom Gerät selbst kommen?“`,style:`sokratisch`,reaction:`„Vom Gerät selbst? ...hm. Er hat da zwei Metallstäbe reingesteckt. Meinst du, das rostet einfach nur blitzschnell im Strom?“`,feedback:`Meisterhaft! Street Epistemology (H.2.2): Du stellst eine Hypothese als gemeinsame Detektivfrage in den Raum. Gerda beginnt selbst nachzudenken (System 2 springt an).`,score:3,nextStepId:`step-3-success`},{text:`„Das klingt wirklich übel. Bevor du noch etwas trinkst, besorge ich dir morgen einen guten Wasserfilter, dann bist du auf der sicheren Seite und kannst endlich wieder ruhig schlafen.“`,style:`ausstieg`,reaction:`„Ja, bitte! Der Mann im Video verkauft genau solche Filter für 1.200 Euro!“`,feedback:`Du meinst es lieb, aber du bestätigst die Angst mit einer Geldausgabe und belohnst indirekt den Schwindel, statt die Behauptung zu klären.`,score:-2,nextStepId:`step-fail`}]},"step-3-success":{id:`step-3-success`,speaker:`Tante Gerda`,speech:`„Du meinst also, der Mann hat das Wasser mit seinen eigenen Stäben verfärbt, um den Leuten Angst zu machen und ihnen teure Filter zu verkaufen? Was für ein Schuft!“`,options:[{text:`„Das wäre zumindest eine naheliegende Erklärung. Lass uns morgen zusammen Kaffee aus ganz normalem Leitungswasser kochen, ich bringe den Kuchen mit.“`,style:`deeskalierend`,reaction:`„Oh, das wäre schön, Kindchen. Kuchen klingt wunderbar. Ich schalte jetzt das Handy aus. Danke, dass du da warst.“`,feedback:`Mission gelungen! Deeskalation, sokratische Frage und echte Zuwendung haben den Kaninchenbau versiegelt, ohne dass Gerda ihr Gesicht verlieren musste.`,score:3}]},"step-3-struggle":{id:`step-3-struggle`,speaker:`Tante Gerda`,speech:`„Ich weiß nicht, was ich noch glauben soll. Mir schwirrt der Kopf...“`,options:[{text:`„Das glaube ich dir, das war heute viel. Lass das Telefon mal liegen, ich komme am Wochenende vorbei und wir gehen eine Runde spazieren. Abgemacht?“`,style:`deeskalierend`,reaction:`„Ja... du hast recht. Ein Spaziergang tut gut.“`,feedback:`Guter Übergang in die Ausstiegsstrategie (H.2.4). Die Beziehung ist geschützt, die Sachfrage bleibt für ein andermal offen.`,score:2}]},"step-fail":{id:`step-fail`,speaker:`Tante Gerda`,speech:`„Ich sehe schon, mit dir kann man darüber nicht reden. Ich kaufe mir jetzt Flaschenwasser und trete der Telegram-Gruppe bei!“ *knallt den Hörer auf*`,options:[{text:`Ende: Gerda fühlte sich nicht gehört und ist jetzt tiefer in der Gruppe. Rechthaben und Helfen sind zweierlei.`,style:`ausstieg`,reaction:`Beim nächsten Mal zuerst das Gefühl ernst nehmen, dann erst über Inhalte reden.`,feedback:`Frage dich: Wollte ich Gerda überzeugen oder beruhigen? Die Empathie-Matrix (H.1.6) ordnet die Reihenfolge.`,score:0}]},"step-panic":{id:`step-panic`,speaker:`Tante Gerda`,speech:`„Wir müssen uns im Keller verbarrikadieren! Ich habe gehört, ab Mitternacht sprühen sie auch aus der Luft!“`,options:[{text:`Ende: Gemeinsame Panik schaukelt sich hoch, weil keiner mehr den ruhigen Gegenpol hält.`,style:`ausstieg`,reaction:`Mitgefühl ja, Mitpanik nein: Wer mitzittert, kann nicht stützen.`,feedback:`Mitfühlende Empathie (H.1.6) heißt, das Gefühl zu verstehen und selbst ruhig zu bleiben, damit Gerda Halt hat.`,score:0}]}}},{id:`scen-michael`,title:`Michaels Heilkristalle`,subtitle:`Street Epistemology & Sokratisches Fragen (H.2.2)`,character:`Michael`,avatar:`🧘‍♂️`,context:`Dein langjähriger Freund Michael hat 800 Euro für ein Set „energetisierter Bergkristalle“ ausgegeben und behauptet, diese würden seine Migräne durch Quantenschwingungen heilen.`,goal:`Verwende reine Street Epistemology: Greife nicht den Kristall an, sondern erforsche seine Methode des Wissenserwerbs.`,bereich:`Freunde`,laenge:`mittel`,ton:`ernst`,bestehenAb:4,lektion:`Michael verteidigt nicht den Stein, sondern seine Erfahrung, sein Geld und sein Selbstbild. Wer zuerst die Freude teilt, nach der Sicherheit fragt und die Methode statt des Ergebnisses erkundet, lässt ihn selbst entdecken, wie man Ursache und Zufall trennt. Der Vorschlag eines fairen Tests ersetzt den Streit durch gemeinsame Neugier.`,toolRef:`H.2.2 Street Epistemology; H.2.3 Die Kunst des aktiven Zuhörens; H.2.1 Die Deeskalations-Matrix`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Michael`,speech:`„Schau mal hier! Dieser Amethyst schwingt auf 432 Hertz und richtet meine Gehirnwellen neu aus. Seit ich ihn nachts auf die Stirn lege, habe ich keine Migräne mehr. Das ist der Beweis, dass Kristalle heilen!“`,options:[{text:`„Michael, ich will dir nichts verderben, aber 432 Hertz ist eine Tonhöhe, und ein Stein schwingt nicht. Für 800 Euro hättest du etwas Vernünftiges bekommen. Da hat dich jemand über den Tisch gezogen.“`,style:`frontal`,reaction:`„Typisch materialistischer Scheuklappen-Blick! Du willst mir meine eigene Heilung absprechen, nur weil die Schulmedizin keine Ahnung von Quantenfeldern hat!“`,feedback:`Frontalangriff gescheitert! Michael verteidigt nun nicht nur den Kristall, sondern sein Ego und seine Investition (Sunk Cost).`,score:-2,nextStepId:`step-fail`},{text:`„Das freut mich riesig, dass die Migräne weg ist! Ehrlich interessiert gefragt: Wie sicher bist du dir auf einer Skala von 0 bis 100 Prozent, dass es der Kristall war?“`,style:`sokratisch`,reaction:`„Danke, Mann, die Schmerzen waren echt die Hölle. Puh, wie sicher? Schon so zu 95%. Ich spüre die Energie ja förmlich kribbeln.“`,feedback:`Guter Einstieg in die Street Epistemology: Freude geteilt, Vertrauen gesichert und den Grad der Überzeugung auf eine Skala gebracht.`,score:3,nextStepId:`step-2`},{text:`„Und wenn du ihn in den Kühlschrank legst, heilt er dann auch Heuschnupfen? Ein Stein, der mit 432 Hertz brummt, müsste man ja hören. Hast du ihn schon mal ans Ohr gehalten, Herr Professor?“`,style:`sarkastisch`,reaction:`„Sehr witzig. Mach dich ruhig lustig, aber du hattest noch nie Migräne, die dich drei Tage ins Bett wirft. Ich hab keinen Bock auf deinen Spott.“`,feedback:`Geistreich, aber auf Michaels Kosten: Spott beschämt, und Beschämte verteidigen sich statt nachzudenken.`,score:-1,nextStepId:`step-fail`}]},"step-2":{id:`step-2`,speaker:`Michael`,speech:`„Ich meine, ich habe den Stein aufgelegt, und am nächsten Morgen war der Schmerz weg. Was soll es denn sonst gewesen sein?“`,options:[{text:`„Das ist der Post-hoc-Fehlschluss, Michael, dazu kommt die Regression zur Mitte: Migräneattacken klingen nach ein, zwei Tagen ohnehin wieder ab. Der Stein hat damit gar nichts zu tun.“`,style:`frontal`,reaction:`„Spar dir deine Fachwörter. Ich kenne meinen Körper besser als deine Statistiken.“`,feedback:`Du hast recht, aber du trittst als Dozent auf. Michael macht wieder dicht.`,score:0,nextStepId:`step-fail`},{text:`„Das verstehe ich gut, so tickt unser Kopf. Aber nimm an, ein Bekannter trinkt gegen Migräne Leitungswasser, glaubt fest daran, und es hilft: Wäre das ein Beweis, dass Wasser Migräne heilt?“`,style:`sokratisch`,reaction:`„Hm... nee, das wäre dann wahrscheinlich der Placebo-Effekt, oder? Weil er dran geglaubt hat... Moment, willst du sagen, bei mir war das auch nur der Glaube?“`,feedback:`Hervorragend! Ein sokratisches Analogie-Experiment. Michael stellt nun von allein die entscheidende Frage, ohne dass du ihn belehren musstest.`,score:3,nextStepId:`step-3`},{text:`„Es kann vieles gewesen sein, Michael: Schlaf, Stress, Wetter, Kaffee, vielleicht auch der Stein. Hast du mal aufgeschrieben, wann deine Anfälle kommen und wann sie ausbleiben, und was an dem Tag los war?“`,style:`sokratisch`,reaction:`„Aufgeschrieben? Nee, nicht wirklich... Stimmt, das könnte man mal machen. Aber wie weiß ich dann, ob es der Stein ist oder was anderes?“`,feedback:`Zweitbester Weg: Das Tagebuch führt zur richtigen Methode, aber du schlägst die Lösung vor, statt Michael die Lücke in seiner eigenen Schlussfolgerung finden zu lassen.`,score:1,nextStepId:`step-3`}]},"step-3":{id:`step-3`,speaker:`Michael`,speech:`„Aber wie könnte ich denn überhaupt herausfinden, ob der Stein wirklich heilende Schwingungen hat oder ob mein Kopf sich das nur selbst geheilt hat?“`,options:[{text:`„Starke Frage! Wie wäre ein Blindtest: Ein Freund steckt den echten Kristall und einen Plastikstein in blickdichte Beutel, du weißt nicht, welcher welcher ist, und testest zwei Wochen?“`,style:`sokratisch`,reaction:`„Ha! Das ist eigentlich eine verdammt coole Idee. Lass uns das mal ausprobieren. Wenn der Stein wirklich Schwingung hat, müsste ich den Unterschied ja spüren!“`,feedback:`Meisterleistung der Street Epistemology: Michael wird vom überzeugten Gläubigen zum neugierigen Forscher.`,score:3},{text:`„Gute Frage, die ich dir nicht allein beantworten kann. Führ ein Migränetagebuch und lass dich beim nächsten Termin ärztlich beraten, dort lässt sich klären, was wirklich hilft und was nicht.“`,style:`deeskalierend`,reaction:`„Ärztlich beraten... na ja, einen Termin hätte ich eh mal wieder gebraucht. Und das Tagebuch kann ich ja nebenher führen.“`,feedback:`Zweitbester Weg (+1): Seriös und fürsorglich, aber du reichst eine fertige Antwort weiter, statt Michael selbst einen Test erfinden zu lassen.`,score:1},{text:`„Ehrlich? Gar nicht, solange du dran glaubst. Dein Kopf ist stärker als jeder Stein. Wenn es dir hilft, behalt ihn einfach, ich will dir deine Überzeugung nicht nehmen.“`,style:`ausstieg`,reaction:`„Na dann ist ja alles gut. Danke fürs Verständnis, ich wusste, dass du mich nicht für einen Spinner hältst.“`,feedback:`Kapitulation im Gewand der Toleranz: Die Freundschaft ist heil, aber die Frage, was wirklich hilft, bleibt offen und Michael bestärkt.`,score:-1}]},"step-fail":{id:`step-fail`,speaker:`Michael`,speech:`„Lass uns einfach nicht mehr darüber reden. Du hast deine Meinung, ich meine Erfahrungen.“`,options:[{text:`Ende: Michael hat sich in die Festung seiner Überzeugung zurückgezogen. Der Stein ist ihm jetzt wichtiger geworden.`,style:`ausstieg`,reaction:`Beim nächsten Mal zuerst nach der Sicherheit fragen, statt den Stein anzugreifen.`,feedback:`Rapoports Regeln und die Street Epistemology (H.2.2) beginnen mit Verstehen, nicht mit Widerlegen.`,score:0}]}}},{id:`scen-stammtisch-chemtrails`,title:`Dieters Himmelsputzer`,subtitle:`Chemtrails, Humor als Brücke & Street Epistemology (H.2.2)`,character:`Dieter`,avatar:`🍺`,context:`Am Stammtisch in deiner Stammkneipe zeigt dein Kumpel Dieter durchs Fenster nach oben. Er ist überzeugt, dass die Streifen am Himmel „Chemtrails“ sind, und hält an der Idee mit einem Augenzwinkern, aber erstaunlich stur fest.`,goal:`Bleib freundlich und lass den Humor die Brücke sein: Frage nach dem Prüfkriterium, statt Dieter zu belehren, und halte den Abend heil.`,bereich:`Freunde`,laenge:`kurz`,ton:`heiter`,bestehenAb:7,lektion:`Dieter glaubt nicht aus Dummheit, sondern aus Lust am Durchblick und Zugehörigkeit am Stammtisch. Humor auf eigene Kosten öffnet Türen, Sarkasmus auf seine Kosten schließt sie. Eine echte Frage („Woran würdest du es merken?“) bringt mehr als jeder Fakt, den du ihm hinwirfst.`,toolRef:`H.2.2 Street Epistemology, H.2.4 Ausstiegs-Strategie, F.1.3 Der Verschwörungsmythos, C.5.3 Atmosphärenphysik`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Dieter`,speech:`„Prost! Und jetzt schau mal nach oben, da: drei Streifen, kreuz und quer. Das ist doch kein Wasserdampf, das ist das Wochenprogramm vom Himmelsputzer! Die sprühen uns das Hirn weich.“ *grinst, hebt das Glas, meint es halb im Ernst*`,options:[{text:`„Bei mir wirkt das Zeug nicht, ich ärgere mich immer noch über jeden Elfmeter. Aber mal ehrlich, Dieter: Woran würdest du merken, dass es normale Kondensstreifen sind?“`,style:`humorvoll`,reaction:`„*lacht* Ha! Elfmeter, das kennt jeder! ...Woran ich das merken würde? Na ja, wenn die Streifen sofort wieder weg wären. Aber viele bleiben stundenlang stehen und verlaufen zu Schleiern. Das ist doch nicht normal!“`,feedback:`Der Scherz auf eigene Kosten öffnet die Tür, die Frage nach dem Prüfkriterium (Widerlegbarkeit) macht aus Behauptung eine gemeinsame Denkaufgabe. Humor als Brücke statt als Waffe (H.2.2, H.2.4).`,score:3,nextStepId:`step-2`},{text:`„Der Himmel ist heute wirklich voll, das stimmt. Magst du mir mal erklären, was die da genau sprühen und wer das bezahlen soll? Ich bin gespannt auf deine Theorie.“`,style:`sokratisch`,reaction:`„Na endlich einer, der zuhört! Aluminium und Barium, sagt mein Schwager, der hat Bodenproben machen lassen. Und warum fliegen die bitte im Gitter, hä?“`,feedback:`Interesse statt Angriff ist gut, aber die Einladung, die Theorie auszubauen, füttert das Narrativ eher, als es zu prüfen. Besser wäre ein Prüfkriterium (H.2.2).`,score:1,nextStepId:`step-2b`},{text:`„Klar, Dieter, und der Mond ist aus Käse. Soll ich dir eine Alufolie für den Hut bestellen, bevor es dich erwischt? Das Bier wird warm, während du den Himmel liest.“`,style:`sarkastisch`,reaction:`„*stellt das Glas ab* Alufolie. Sehr witzig. Wenn du alles besser weißt, kannst du ja allein weitertrinken.“`,feedback:`Geistreich, aber auf seine Kosten: Der Witz wertet den Menschen ab (D.1.1). Dieter verteidigt jetzt seinen Stolz statt seine Behauptung.`,score:-2}]},"step-2":{id:`step-2`,speaker:`Dieter`,speech:`„*kratzt sich am Kinn* Ja, gut, wenn der Streifen nach zwei Sekunden weg wäre... aber da hinten, der steht seit einer Stunde! Und der Flieger davor hat gar keinen gemacht. Wie erklärst du mir das, Herr Schlau?“`,options:[{text:`„Interessant, dass einer bleibt und einer nicht. Was, wenn die Luft oben mal feuchter und mal trockener ist? Wie könnten wir das prüfen?“`,style:`sokratisch`,reaction:`„*brummt* Feuchter und trockener... Hm. Das hat mir mal ein Pilot beim Grillen erzählt, glaube ich. Mit Wetterbericht vergleichen? Das könnte man machen.“`,feedback:`Du bietest eine alternative Erklärung als Frage an und lässt Dieter die Prüfung selbst vorschlagen. Das hält ihn im Denkmodus (System 2) statt im Verteidigungsmodus (H.2.2, E.1.1).`,score:3,nextStepId:`step-3`},{text:`„Das ist Eiskristall-Physik, Dieter: Der Wasserdampf aus den Abgasen gefriert in der Kälte oben und bleibt in feuchter Luft stehen. Punkt. Lies es halt mal nach.“`,style:`frontal`,reaction:`„Nachlesen! Im Internet steht, was die wollen. Noch ein Bier?“ *dreht sich zum Wirt*`,feedback:`Sachlich stimmig, aber als fertiges Urteil geliefert: Du ersparst ihm die eigene Entdeckung, und „Lies nach“ klingt nach Besserwisserei. Gut gemeint, aber ohne Wirkung.`,score:0},{text:`„Na ja, vielleicht ist da schon was dran. Man weiß ja nie, was die da oben alles treiben, und ich will ja keinen Streit. Noch eine Runde, Dieter?“`,style:`ausstieg`,reaction:`„Siehst du! Endlich einer mit Durchblick. Morgen bringe ich dir meine Fotosammlung mit, dann kannst du dir selbst ein Bild machen.“`,feedback:`Kapitulation: Du kaufst dir den Frieden mit einer Scheinzustimmung und bestätigst die Behauptung. Ehrlich wäre gewesen: neugierig bleiben, ohne zuzustimmen (H.2.4).`,score:-1}]},"step-2b":{id:`step-2b`,speaker:`Dieter`,speech:`„Und das Barium im Boden, das ist doch der Beweis! Wenn das da nicht hingehört, warum ist es dann da? Hä? Sag mal was, Schlauberger.“ *tippt auf den Tisch*`,options:[{text:`„Messen ist gut! Welches Labor hat das gemacht, und womit wurde die Probe verglichen? Mich würde interessieren, wie man da sicher sein kann.“`,style:`sokratisch`,reaction:`„Das... weiß ich gar nicht, ehrlich gesagt. Muss ich meinen Schwager fragen. Aber den frage ich nur, wenn du das nächste Bier zahlst.“`,feedback:`Die Frage nach Methode und Vergleichsprobe prüft den Weg zum Wissen, nicht den Menschen (H.2.2). Gutes Ende, aber der Faden zu den Kondensstreifen ist weg.`,score:2},{text:`„Aluminium und Barium sind in jedem Boden, Dieter. Ein großer Teil der Erdkruste besteht aus Aluminiumverbindungen. Das beweist also gar nichts.“`,style:`frontal`,reaction:`„Aha, du weißt es wieder besser. Dann erzähl dem Himmel, was er sprühen darf. Prost.“`,feedback:`Die Fakten stimmen, aber du sprichst im Ton des Rechthabens. So hört Dieter nur „Du irrst“ und geht in die Abwehr.`,score:0},{text:`„Oh Mann, Barium im Boden und Streifen im Gitter... Du machst mir langsam echt Angst, Dieter. Sollen wir bei der Behörde nachfragen?“`,style:`affektiv`,reaction:`„Genau! Und die geben dir nur Standardantworten. Ich habe die Mailadresse schon, soll ich dir die geben?“`,feedback:`Mitpanik: Du spiegelst seine Sorge, ohne einen Anker zu bieten. Aus dem Scherz am Stammtisch wird ein Projekt.`,score:-1}]},"step-3":{id:`step-3`,speaker:`Dieter`,speech:`„*brummt* Pilot, Wetterbericht... gut. Aber wenn ich mich irre, muss ich dann meine ganze Himmelsfotosammlung wegwerfen? Das sind 200 Bilder, Mann!“`,options:[{text:`„Quatsch, die bleiben! Wir hängen sie als ‚Schönste Wolkenbilder' im Vereinsheim auf. Und beim nächsten Streifen vergleichen wir mit dem Wetterbericht.“`,style:`humorvoll`,reaction:`„Wolkenbilder... klingt fast nach Kunst. Aber ich warne dich: Wenn der Wetterbericht nichts von feuchter Höhenluft sagt, zahlst du die nächste Runde!“ *lacht, stößt an*`,feedback:`Du rettest sein Gesicht (Fotos bleiben, Dieter ist Künstler statt Irrender) und machst die Prüfung zum gemeinsamen Spiel. Humor, der verbindet, dazu eine Wette, die die Wetterdaten entscheiden lassen, nicht ihr beide.`,score:3},{text:`„Du musst gar nichts wegwerfen. Mach doch eine Strichliste: wann ein Streifen bleibt, wann nicht, und vergleich das später mit dem Wetterbericht.“`,style:`deeskalierend`,reaction:`„Strichliste auf dem Bierdeckel... na gut, kann ich ja mal probieren. Aber ich sage dir gleich: Ich glaube trotzdem, was ich sehe.“`,feedback:`Gute Spur, praktisch und ohne Gesichtsverlust. Es fehlt nur noch die Wärme, die ihm den Ausweg schmackhaft macht.`,score:1},{text:`„Ja, die kannst du wegwerfen, Dieter. Gib doch einfach zu, dass du dich geirrt hast, dann sind wir fertig mit dem Thema und können endlich über das Wochenende reden.“`,style:`frontal`,reaction:`„Gar nichts geb ich zu!“ *Bierdeckel klatscht auf den Tisch* „Ich bin hier nicht vor Gericht!“`,feedback:`Erzwungenes Zugeständnis: Wer sich öffentlich geschlagen geben soll, klammert sich fester an die Behauptung (E.1.2 Kognitive Dissonanz).`,score:-2}]}}},{id:`scen-kollegin-globuli`,title:`Karins Globuli`,subtitle:`Placebo, natürlicher Verlauf & Mitfühlende Empathie (H.2.2, C.4.5)`,character:`Karin`,avatar:`🍵`,context:`Du stehst erkältet in der Teeküche, als deine Kollegin Karin dir eine Dose Globuli zuschiebt. Sie fragt dich offen, warum du so skeptisch guckst, und kollegiale Stimmung steht auf dem Spiel.`,goal:`Würdige ihre Fürsorge, erkunde ihre Erfahrung mit Fragen (statt zu urteilen) und nenne am Ende klar, dass bei Fieber oder ausbleibender Besserung ärztliche Abklärung gehört.`,bereich:`Arbeit`,laenge:`kurz`,ton:`ernst`,bestehenAb:7,lektion:`Karins Rat kommt aus Fürsorge, nicht aus Dummheit: Das Motiv ist Zuwendung. Erst wenn du ihre Erfahrung ernst nimmst, kann die Frage nach dem natürlichen Verlauf (C.4.6) wirken. Gesundheitsfragen brauchen am Ende eine klare, freundliche Grenze: bei Fieber oder ausbleibender Besserung zum Arzt.`,toolRef:`H.2.2 Street Epistemology, H.1.3 Intellektuelle Barmherzigkeit, C.4.5 Placebo-Effekt, C.4.6 Regression zur Mitte, F.2.2 Homöopathie`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Karin`,speech:`„*schiebt dir eine kleine Dose über den Küchentisch* Du klingst ja furchtbar! Nimm die Globuli, die haben mir immer geholfen. Und sag mal, warum guckst du eigentlich so skeptisch? Glaubst du nur an Chemie?“`,options:[{text:`„Danke, dass du dir Sorgen machst, Karin. Ja, ich gucke skeptisch. Erzähl mal: Wann haben sie dir zuletzt geholfen, und woran hast du es gemerkt?“`,style:`sokratisch`,reaction:`„Oh, das ist ehrlich gemeint? ...Vor zwei Monaten, mit Husten! Drei Tage Globuli, und ich war wieder fit. Meine Ärztin hätte mir nur Hustensaft aufgeschrieben.“`,feedback:`Erst Beziehung würdigen, dann die Erfahrung erkunden: Du nimmst die Person, ohne die Wirkung zu bestätigen (H.1.3, H.2.3). Gutes Fundament für das Weiterfragen.`,score:3,nextStepId:`step-2`},{text:`„Danke, aber ich nehme lieber nichts. Ich gucke so, weil ich Zuckerkügelchen nicht für Medizin halte, aber ich möchte darüber keinen Streit anfangen.“`,style:`ausstieg`,reaction:`„Zuckerkügelchen? *zieht eine Augenbraue hoch* Hast du das mal richtig nachgelesen oder plapperst du nur nach, was alle sagen?“`,feedback:`Ehrlich und höflich, aber das Urteil „Zucker“ steht im Raum wie eine Ohrfeige. Du hast den Streit trotzdem eröffnet (H.2.4).`,score:1,nextStepId:`step-2b`},{text:`„Karin, Globuli sind Zucker, da ist nichts drin, das ist längst bewiesen. Das ist reines Placebo, und du fällst darauf rein.“`,style:`frontal`,reaction:`„Placebo? Mir hat es geholfen, und du stellst mich hin, als wäre ich naiv! Ich wollte dir nur etwas Gutes tun.“ *nimmt die Dose zurück*`,feedback:`Zu schnell und zu hart: Du bewertest ihre Erfahrung („du fällst darauf rein“) und beschämst sie. Placebo-Effekt (C.4.5) ist ein spannender Punkt, aber nur als Frage.`,score:-2}]},"step-2":{id:`step-2`,speaker:`Karin`,speech:`„Eben! Seitdem schwöre ich darauf. Das war doch kein Zufall, oder? Ich habe nichts anderes genommen, nur die Kügelchen, und nach drei Tagen war der Husten weg.“`,options:[{text:`„Schön, dass du wieder fit warst. Wie lange dauert so ein Husten bei dir sonst, wenn du nichts nimmst? Könnte er von selbst abgeklungen sein?“`,style:`sokratisch`,reaction:`„*überlegt* Normalerweise dauert so was bei mir eine knappe Woche... also, vielleicht ist es von alleine gegangen? Hm. Aber es hat sich so gut angefühlt!“`,feedback:`Du fragst nach dem natürlichen Verlauf, ohne zu urteilen (C.4.6 Regression zur Mitte). Karin findet die Alternativerklärung selbst und kann sie ohne Gesichtsverlust prüfen.`,score:3,nextStepId:`step-3`},{text:`„Das war Regression zur Mitte: Erkältungen gehen von selbst weg, meist nach einer knappen Woche. Dass du Globuli genommen hast, ist reiner Zufall und beweist gar nichts.“`,style:`frontal`,reaction:`„Also ist alles Zufall, was mir hilft. Danke für die Belehrung.“ *dreht sich zur Spüle um*`,feedback:`Inhaltlich richtig, aber als Vortrag verpackt. Karin wird nicht entdecken, sondern vorgeführt, und schaltet ab.`,score:0},{text:`„Wenn es dir geholfen hat, ist doch alles gut. Jeder, wie er mag. Ich hole mir jetzt auch einen Tee, und dann ist das Thema für uns beide durch, einverstanden?“`,style:`ausstieg`,reaction:`„Siehst du, du brauchst auch mal was Natürliches! Ich stelle dir die Dose hin, nimm ruhig drei am Tag.“`,feedback:`Kapitulation: Du weichst aus und lässt die Behauptung unwidersprochen stehen. Karin hört darin Zustimmung (H.2.4 setzt Ehrlichkeit voraus).`,score:-1}]},"step-2b":{id:`step-2b`,speaker:`Karin`,speech:`„Wenn du so sicher bist, dann sag mir doch, was du an Beweisen hast. Mir hat es nämlich geholfen, und das ist für mich auch ein Beweis.“`,options:[{text:`„Gute Frage. Sag du mir zuerst: Was müsste passieren, damit du glaubst, dass sie nicht wirken? Dann sage ich dir, was mich überzeugen würde.“`,style:`sokratisch`,reaction:`„Hm... das habe ich mich noch nie gefragt. Vielleicht, wenn zwei Gruppen verglichen würden und bei beiden das Gleiche passiert? Lass uns später mal reden, die Kaffeemaschine ist fertig.“`,feedback:`Du tauschst die Beweislast gegen ein gemeinsames Kriterium (H.2.2). Gutes Ende, aber ohne das tiefere Verstehen ihrer Erfahrung.`,score:2},{text:`„Ich habe es nachgelesen: Die Wirkstoffe sind so stark verdünnt, dass praktisch keiner mehr in den Kügelchen steckt. Das ist in Übersichtsarbeiten nachzulesen.“`,style:`frontal`,reaction:`„Aha, du weißt es besser als die Heilpraktikerin. Na dann. Gute Besserung, brauchst du ja nicht.“`,feedback:`Die Fakten stimmen (F.2.2), aber du setzt dein Wissen als Autorität ein (D.1.4). So verteidigt Karin ihre Erfahrung statt ihrer Argumente.`,score:0},{text:`„Ach, und Knochenbrüche heilst du dann auch mit Zuckerwasser? Aber danke fürs Angebot, Karin, ich bleibe lieber bei meinem Tee.“`,style:`sarkastisch`,reaction:`„Das war überflüssig. Ich wollte dir helfen, und du machst dich lustig. *nimmt die Dose und geht*“`,feedback:`Sarkasmus auf ihre Kosten: Das ist Strohmann (D.1.2) plus Spott. Karin zieht sich beleidigt zurück, und die Teeküche wird für Wochen zur Sperrzone.`,score:-2}]},"step-3":{id:`step-3`,speaker:`Karin`,speech:`„*nachdenklich* Eine Woche, ja... Vielleicht wäre es wirklich von allein gegangen. Aber ich will nicht, dass du mich für leichtgläubig hältst. Und du: Was machst du jetzt gegen deine Erkältung?“`,options:[{text:`„Ich halte dich nicht für leichtgläubig. Ich trinke Tee, schlafe viel und gehe zum Arzt, wenn Fieber kommt oder es nicht besser wird. Und du?“`,style:`deeskalierend`,reaction:`„Das ist vernünftig. Das mache ich auch so. Und die Dose lasse ich trotzdem hier stehen, falls du es dir anders überlegst. Gute Besserung!“`,feedback:`Du würdigst ihre Denkleistung, bleibst bei deinem Weg und nennst die Grenze: ärztliche Abklärung bei Fieber oder ausbleibender Besserung. Beziehung gewahrt, Rat gegeben.`,score:3},{text:`„Tee, Bett und Geduld. Und bevor du fragst: Bei Fieber gehe ich lieber zum Arzt, auch wenn deine Kügelchen sicher gut gemeint sind. Nichts für ungut, Karin!“`,style:`humorvoll`,reaction:`„Gut gemeint sind sie immer! Aber Arzt bei Fieber, da hast du recht. Ich schiebe dir die Dose trotzdem rüber, schaden tut sie nicht.“`,feedback:`Freundlich und klar, aber der Teil „deine Kügelchen“ kippt leicht ins Belächeln. Gute Kernbotschaft mit kleiner Reibung.`,score:1},{text:`„Es war also Zufall. Und wer dir solche Kügelchen verkauft, verdient daran, dass Leute das nicht merken. Du solltest da nicht mehr hingehen, Karin.“`,style:`frontal`,reaction:`„Jetzt ist es aber genug. Du hast kein Recht, mir zu sagen, wohin ich gehe.“ *nimmt ihre Tasse und verlässt die Küche*`,feedback:`Aus einer gemeinsamen Entdeckung wird ein Pauschalverdacht gegen alle, die so etwas anbieten (D.1.1), mit Verbotston. Karin rettet ihre Autonomie, indem sie geht.`,score:-2}]}}},{id:`scen-opa-kettenbrief`,title:`Opas Kettenbrief`,subtitle:`Kettenbriefe, Angst & Intellektuelle Barmherzigkeit (H.1.3, D.2.1)`,character:`Opa Horst`,avatar:`👴`,context:`In der Familien-WhatsApp-Gruppe postet dein Opa Horst eine dringende Warnung samt Aufforderung, sie an zehn Personen weiterzuleiten. Die Gruppe schweigt betreten, und alle schauen, was du tust.`,goal:`Nimm Opas Fürsorge ernst, ohne ihn vor der Familie bloßzustellen, und lade ihn ein, die Warnung selbst zu prüfen.`,bereich:`Familie`,laenge:`kurz`,ton:`heiter`,bestehenAb:7,lektion:`Opa teilt aus Fürsorge, nicht aus Dummheit: Kettenbriefe leben von Angst und Pflichtgefühl. Eine neugierige Frage und eine gemeinsame Prüfung bringen mehr als der Hinweis „Fake“, und ein Ausweg mit Würde („Entwarnung“) hält Opa im Gespräch.`,toolRef:`H.1.3 Intellektuelle Barmherzigkeit, H.2.2 Street Epistemology, D.2.1 Appell an die Emotionen, A.1.2 Hanlons Rasiermesser`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Opa Horst`,speech:`*postet in die Familiengruppe, mit sieben Warndreiecken* „ACHTUNG!!! WhatsApp wird ab morgen kostenpflichtig, außer ihr leitet diese Nachricht an 10 Leute weiter!!! Hat mir der Hans aus dem Schützenverein geschickt, der kennt sich aus. Schnell, bevor es zu spät ist!!!“`,options:[{text:`„Danke fürs Warnen, Opa! Ich leite es gleich an zehn Leute weiter. Nur vorab: Wer kontrolliert eigentlich, ob ich wirklich zehn erreicht habe?“`,style:`humorvoll`,reaction:`„*schreibt langsam* Ha! Kontrolliert... Na, WhatsApp natürlich. Die haben ja alle unsere Daten. Oder? Hm.“`,feedback:`Zuwendung zuerst, dann eine Frage, die die Logik des Kettenbriefs spielerisch sichtbar macht (H.2.2). Opa bleibt der Warner und merkt von selbst, wo die Geschichte wackelt.`,score:3,nextStepId:`step-2`},{text:`„Lieb von dir, dass du uns warnst, Opa. Ich schaue kurz nach, ob an der Sache etwas dran ist, und melde mich dann in Ruhe bei dir zurück, versprochen.“`,style:`deeskalierend`,reaction:`„Nachschauen? Mach das mal, du kennst dich ja mit dem Internet aus. Aber sag es nicht allen, sonst denken sie, ich sei... na ja. Stellst du mir das Ergebnis in die Gruppe?“`,feedback:`Respektvoll und ruhig, aber du übernimmst die Prüfung für ihn. Opa bleibt Zuschauer, und der Lerneffekt ist kleiner (H.2.3).`,score:1,nextStepId:`step-2b`},{text:`„Opa, das ist ein uralter Kettenbrief, so ein Quatsch! Bitte hör auf, den Mist in der Gruppe zu verteilen, das nervt alle, und ich hab auch noch zu tun.“`,style:`frontal`,reaction:`„*kleinlaut* Ich wollte euch doch nur warnen. Dann sage ich eben gar nichts mehr. Ihr nehmt mich ja sowieso nicht ernst.“`,feedback:`Die Sache stimmt, aber „Quatsch“ und „Mist“ treffen den Menschen, der aus Fürsorge handelt. Opa zieht sich zurück und die Gruppe verliert ihn (H.1.3).`,score:-2}]},"step-2":{id:`step-2`,speaker:`Opa Horst`,speech:`„Na, das merken die schon irgendwie... Der Hans hat gesagt, es kommt von der Polizei, und der Hans ist doch kein Lügner. *tippt langsam* Warum sollte der mich anlügen?“`,options:[{text:`„Hans lügt bestimmt nicht, er glaubt es ja selbst. Wollen wir zusammen nachsehen, was WhatsApp dazu schreibt? Dann wissen es auch alle im Verein.“`,style:`sokratisch`,reaction:`„Gemeinsam nachsehen? Das ist eine gute Idee! *Tippgeräusche* ...Moment, auf deren Seite steht dazu gar nichts von Weiterleiten.“`,feedback:`Du trennst die Person (Hans meint es gut) von der Quelle (Kettenbrief) und lädst Opa zur gemeinsamen Prüfung ein. Seziert wird die Behauptung, nicht der Mensch (H.2.2, A.1.2 Hanlon).`,score:3,nextStepId:`step-3`},{text:`„Opa, Nachrichten mit ‚sonst passiert etwas' sind fast immer Fake, und diese hier ist ein Klassiker. Einfach löschen, fertig, da ist wirklich nichts dran, glaub mir.“`,style:`frontal`,reaction:`„Löschen... und wenn doch was dran ist? Ich schicke es lieber sicherheitshalber noch an die Elfriede, die hat ja auch ein Handy.“`,feedback:`Regel richtig, aber ohne Weg dorthin. Opa kann die Regel nicht nachvollziehen und entscheidet sich für „sicher ist sicher“. Gut gemeint, kaum Wirkung.`,score:0},{text:`„Na gut, Opa, vielleicht leiten wir es besser einfach weiter. Kostet ja nichts, und sicher ist sicher. Dann haben wir Ruhe, und Hans freut sich auch noch.“`,style:`ausstieg`,reaction:`„Siehst du! Ich bin gleich bei 37 Kontakten. Der Hans wird stolz auf mich sein!“`,feedback:`Kapitulation: Du stärkst den Mechanismus des Kettenbriefs, der auf Angst und Pflichtgefühl baut (D.2.1 Appell an die Emotionen). Opa lernt: Es lohnt sich, mitzumachen.`,score:-1}]},"step-2b":{id:`step-2b`,speaker:`Opa Horst`,speech:`„Und was schreibst du dann? Dass der Hans sich geirrt hat? Dann ist er doch beleidigt. Oder dass ich es war, der es reingestellt hat?“`,options:[{text:`„Ich schreibe, dass du als Erster Alarm geschlagen hast. Dafür gibt es den Titel ‚Wachsamster Opa'. Die Auflösung bekommst du persönlich von mir.“`,style:`humorvoll`,reaction:`„‚Wachsamster Opa'! *lacht* Das gefällt mir. Dann hänge ich mir gleich einen Stern an die Jacke.“`,feedback:`Du gibst dem Opa einen Platz, an dem er sein Gesicht wahrt (H.2.4): Er hat gewarnt, nicht geirrt. Guter Abschluss, der Lerneffekt bleibt aber klein.`,score:2},{text:`„Das Ergebnis schicke ich dir privat, Opa. In der Gruppe lasse ich es lieber, damit es keinen Wirbel gibt und sich niemand schlecht fühlt, ja?“`,style:`deeskalierend`,reaction:`„Gut, dann bleibt es unter uns. Aber die anderen glauben dann weiter, dass es kostenpflichtig wird.“`,feedback:`Schonend für Opa, aber die Gruppe bleibt im Irrtum, und die Warnung steht weiter im Chat. Kein Schaden, aber auch kein Gewinn.`,score:1},{text:`„Oh Gott, und wenn es doch stimmt? Dann leiten wir es besser alle schnell weiter, sicherheitshalber. Ich mache gleich mit, Opa, ich schicke es auch.“`,style:`affektiv`,reaction:`„Siehst du, du bist ein kluger Junge. Ich schicke es gleich noch an die Elfriede und an den Pfarrer.“`,feedback:`Mitpanik: Wer die Angst teilt, statt sie zu prüfen, verteilt den Kettenbrief mit. Der Mechanismus lebt von genau dieser Reaktion.`,score:-1}]},"step-3":{id:`step-3`,speaker:`Opa Horst`,speech:`„Das steht ja gar nicht auf deren Seite... Dann habe ich 23 Leuten Angst gemacht! Wie peinlich. *Pause* Was sage ich denn jetzt dem Hans?“`,options:[{text:`„Gar nicht peinlich, Opa: Du hast als Erster nachgeprüft. Schreib in die Gruppe ‚Entwarnung: Warnung geprüft, falsch.' Das ist die bessere Nachricht.“`,style:`humorvoll`,reaction:`„Das gefällt mir! ‚Gegengeprüfte Entwarnung', das klingt wie bei der Zeitung. Ich schicke es gleich an alle. Aber an die 23, nicht an 10!“`,feedback:`Du gibst Opa Würde zurück und eine Rolle: nicht Fehler, sondern Aufklärung. Humor verbindet, die Korrektur geht an dieselben Leute wie die Warnung.`,score:3},{text:`„Schreib ihm doch einfach, dass du nachgeschaut hast. Der Hans hat es bestimmt auch nur weitergeleitet, so wie alle anderen vor ihm auch, ganz ohne Absicht.“`,style:`deeskalierend`,reaction:`„Ja, das stimmt wohl. Ich schreibe es ihm nachher in Ruhe. Aber den anderen sage ich lieber nichts, sonst lachen sie mich aus.“`,feedback:`Entlastend und richtig, aber die 23 Empfänger bleiben im Ungewissen. Der Lerneffekt bleibt auf Hans und Opa beschränkt.`,score:1},{text:`„Ach, die 23 sind nicht so schlimm. Aber nächstes Mal prüfst du bitte erst, ja? Wir können nicht ständig dein Handy kontrollieren, das ist anstrengend.“`,style:`frontal`,reaction:`„*Pause* Ich war ja nur... na gut. Dann frage ich künftig lieber gar nichts mehr und schreibe nichts mehr.“`,feedback:`Die erleichterte Stimmung kippt: Opa hört „Du bist ein Problem“. Der Schritt zur Selbstprüfung wird mit Belehrung bestraft (H.1.3).`,score:-1}]}}},{id:`scen-date-sternzeichen`,title:`Skorpion beim Dinner`,subtitle:`Humor, Barnum-Effekt & leichtes Fragen (H.2.2, B.10 Barnum-Effekt, F.2.1 Astrologie)`,character:`Sam`,avatar:`🍷`,context:`Erstes Date, Restaurant, der Wein ist schon halb leer. Sam hat beobachtet, wie du die Speisekarte studierst, und fragt nach deinem Sternzeichen. Du bist Skorpion.`,goal:`Bleibe charmant und neugierig, statt zu belehren. Mach aus dem Horoskop-Spruch ein Spiel, das beiden Spaß macht und zeigt, wie wenig ein Kalenderdatum über einen Menschen verrät.`,bereich:`Freunde`,laenge:`kurz`,ton:`heiter`,bestehenAb:6,lektion:`Beim Flirten gewinnt nicht, wer recht hat, sondern wer zum Lachen bringt und zum Fragen einlädt. Ein Mini-Experiment mit zwei Beschreibungen zeigt den Barnum-Effekt, ohne dass du jemanden belehren musst, und führt dich zur eigentlich interessanten Frage: Wer bist du, jenseits deines Sternzeichens?`,toolRef:`H.2.1, H.2.2, B.10, F.2.1, A.1.1`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Sam`,speech:`*nippt am Wein* „Moment, du bist Skorpion? Na klar, das erklärt alles. Wie du die Speisekarte studiert hast, als wäre sie ein Verhör. Typisch Skorpion!“`,options:[{text:`„Sternzeichen erklären nichts, dafür gibt es keinen Beleg. Wie sich ein Mensch verhält, hängt nicht vom Geburtsmonat ab, sondern von ganz anderen Dingen.“`,style:`frontal`,reaction:`„Oh. Okay. Ich wollte nur flirten, aber gut, du bist ja im Vortragsmodus. Die Rechnung, bitte.“`,feedback:`Sachlich richtig, aber du antwortest einem Flirt mit einem Referat. Aus einem Spiel wird ein Streit, und das Date hat keine Chance mehr.`,score:-2},{text:`„Ich habe die Karte so lange studiert, damit du Zeit zum Flirten hast. Du kennst mein Sternzeichen vor meinem Nachnamen: Wer ermittelt hier gegen wen?“`,style:`humorvoll`,reaction:`*lacht* „Erwischt! Ich habe vorab ein bisschen recherchiert, Skorpion. Aber das gilt nicht als Beweis!“`,feedback:`Gelungener Humor: Du drehst den Spieß charmant um, ohne anzugreifen, und das Gegenüber lacht mit. Die Tür für das Thema steht offen.`,score:3,nextStepId:`step-2`},{text:`„Ja, wir Skorpione sind gefährlich: erst die Vorspeise, dann dein Herz. Pass gut auf, du sitzt hier mit einem echten Profi am Tisch.“`,style:`humorvoll`,reaction:`„Ooh, ich habe Angst. Aber ich bleibe sitzen, das Risiko nehme ich in Kauf.“`,feedback:`Charmant, aber du spielst das Klischee mit und bestätigst es indirekt. Das Gespräch bleibt leicht, kommt aber nirgends hin.`,score:1,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Sam`,speech:`*grinst* „Ertappt. Aber im Ernst, stimmt doch: Skorpione sind eifersüchtig, verschlossen und nachtragend. Sag nicht, dass das nicht auf dich zutrifft!“`,options:[{text:`„Ich mache dir ein Angebot: Ich lese zwei Beschreibungen vor, eine ist mein Horoskop, eine erfunden. Wer sie nicht auseinanderhält, zahlt das Dessert.“`,style:`humorvoll`,reaction:`„Das Dessert nehme ich! ... *hört zu, rät, lacht* Moment, ich hätte beide für dich gehalten. Das ist unfair.“`,feedback:`Ein spielerisches Mini-Experiment: Vage Beschreibungen passen auf fast jeden (Barnum-Effekt). Sam entdeckt es selbst und lacht darüber.`,score:3,nextStepId:`step-3`},{text:`„Nachtragend? Ich habe dem Kellner den vergessenen Aperitif noch nicht verziehen. Aber verschlossen? Ich habe dir in einer Stunde mein halbes Leben erzählt!“`,style:`humorvoll`,reaction:`„Stimmt, verschlossen bist du nicht. Eifersüchtig muss ich aber noch testen. Das Dessert könnte der Test sein.“`,feedback:`Schlagfertig und selbstironisch, doch du entkräftest nur die Klischees einzeln und bleibst im Horoskopmodus statt es zu entzaubern.`,score:1,nextStepId:`step-3`},{text:`„Eifersüchtig?! Wer hat dir das erzählt? Bin ich überhaupt nicht, und verschlossen schon gar nicht, ich bin ein offenes Buch, frag, was du willst!“`,style:`affektiv`,reaction:`„Offenes Buch, aber mit Alarmanlage. Gut, ich notiere: Eifersucht lieber nicht ansprechen.“ *lacht, aber etwas weniger*`,feedback:`Die Verteidigung wirkt wie ein Treffer: Wer so heftig dementiert, bestätigt das Klischee. Das Spiel kippt zu deinen Lasten.`,score:-1}]},"step-3":{id:`step-3`,speaker:`Sam`,speech:`„Okay, okay, die Sterne haben gerade verloren. Aber jetzt bin ich neugierig: Wenn nicht dein Sternzeichen, was erklärt dich dann?“`,options:[{text:`„Das findest du im Gespräch heraus, nicht im Kalender. Mein Vorschlag: eine Frage pro Gang, du fragst, ich antworte ehrlich, dann tauschen wir.“`,style:`sokratisch`,reaction:`„Eine Frage pro Gang? Abgemacht. Erste Frage: Warum hast du eigentlich Skorpion in deiner Dating-App angegeben?“`,feedback:`Du machst aus der Frage ein gemeinsames Spiel, in dem echte Fragen zählen. Das Gespräch geht zum Menschen, nicht zum Sternzeichen.`,score:3},{text:`„Mein Verhalten erklärt sich aus Hunger, Charme und einer gewissen Schwäche für Tiramisu. Der Rest ist Zufall, vielleicht ein bisschen Mondphase.“`,style:`humorvoll`,reaction:`„Tiramisu, Zufall, Mondphase. Ich bin überzeugt, das ist die wissenschaftlichste Theorie, die ich heute gehört habe.“`,feedback:`Sympathisch und witzig, aber die Chance auf ein echtes Gespräch lässt du verstreichen. Das Date bleibt nett, ohne dass es vertraut wird.`,score:1},{text:`„Vermutlich Erziehung, Gene und Lebenserfahrung. Aber erkläre du mir mal, warum jemand mit deiner Intelligenz an Kaffeesatz glaubt.“`,style:`sarkastisch`,reaction:`„Kaffeesatz? Autsch. Und ich dachte, das wird heute noch was.“ *schaut ins Glas*`,feedback:`Geistreich, aber auf Kosten des Gegenübers: Du gewinnst den Punkt und verlierst die Stimmung. Sarkasmus beim ersten Date ist ein Risiko.`,score:-1}]}}},{id:`scen-nichte-warum`,title:`Emma und das endlose Warum`,subtitle:`Ehrlich sagen „Ich weiß es nicht“ statt zu bluffen (H.2.2, A.17)`,character:`Emma`,avatar:`👧`,context:`Du sitzt mit deiner siebenjährigen Nichte Emma auf einer Parkbank. Sie schaut in den Himmel und fragt: „Warum ist der Himmel blau?“ Du ahnst schon: Das ist erst der Anfang einer langen Warum-Kette.`,goal:`Beantworte ehrlich, was du weißt, und sage „Das weiß ich nicht, wie finden wir es heraus?“, wenn du an die Grenze kommst, statt zu bluffen.`,bereich:`Familie`,laenge:`kurz`,ton:`heiter`,bestehenAb:8,lektion:`Kinder merken, wenn Erwachsene bluffen, und lernen aus unserer Haltung mehr als aus der Antwort. „Das weiß ich nicht, wie finden wir es heraus?“ ist der beste Satz der Neugier: Er hält die Wissenschaft in Gang und zeigt, dass Nichtwissen kein Gesichtsverlust ist. Der Himmel ist blau, weil die Luft kurzwelliges Licht stärker streut (Rayleigh-Streuung).`,toolRef:`H.2.2, A.17, A.16`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Emma`,speech:`*hüpft neben der Parkbank, zeigt mit dem ganzen Arm nach oben* „Du! Warum ist der Himmel blau? Aber nicht ‚Weil er halt blau ist‘, das sagt Papa immer!“`,options:[{text:`„Das ist ganz einfach, Emma: Der Himmel spiegelt das Meer. Weil das Wasser blau ist, ist der Himmel auch blau. Na, alles klar, kleine Forscherin?“`,style:`ausstieg`,reaction:`„Aber ... in der Wüste ist doch gar kein Meer, und da ist der Himmel auch blau! *verschränkt die Arme* Du hast dich verflunkert.“`,feedback:`Bluffen, um nicht „Ich weiß nicht“ sagen zu müssen: Das Meer-Märchen ist falsch (Wasser sieht blau aus, weil es rotes Licht stärker schluckt; der Himmel hat einen eigenen Grund), und Kinder merken Widersprüche schneller, als man glaubt.`,score:-2,nextStepId:`step-bluff`},{text:`„Gute Frage! Das Sonnenlicht enthält alle Farben, und die Luft streut das kurzwellige Blau stärker als das Rot. Das nennt man Rayleigh-Streuung, Emma.“`,style:`frontal`,reaction:`„Rei-ligh was? *runzelt die Stirn* Das ist ein komisches Wort. Aber warum streut die Luft das Blau mehr als das Rote?“`,feedback:`Die Antwort stimmt, ist aber zu groß und zu fachlich für eine Siebenjährige. Es geht ehrlich weiter, aber das Warum landet direkt bei der Grenze deines Wissens.`,score:1,nextStepId:`step-2`},{text:`„Super Frage! Sonnenlicht steckt voller Farben, und die Luft schubst das Blau am stärksten umher, wie ein Flipper. So kommt Blau von überall.“`,style:`humorvoll`,reaction:`„Wie ein Flipper! *lacht und hüpft* Und warum schubst die Luft das Blau mehr als das Rote? Und warum ist es abends rot? Und warum ...?“`,feedback:`Ehrlich, bildhaft und im richtigen Maß vereinfacht: Blau (kurze Wellenlänge) wird in der Luft stärker gestreut als Rot (Rayleigh-Streuung). Das Bild des Flippers weckt Neugier statt Unsicherheit.`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Emma`,speech:`*zupft am Ärmel, die Augen groß wie Untertassen* „Aber WARUM streut die Luft das Blau mehr als das Rote? Und warum hat Blau diese Dings ... Wellen? Und warum ...“`,options:[{text:`„Weil Blau eben schneller schwingt, so wie beim Sport. Blau ist halt sportlicher als Rot, deshalb streut es mehr. Das lernst du aber erst in der Schule, Emma, glaub mir.“`,style:`ausstieg`,reaction:`„Sport? Aber Licht macht doch keinen Sport! *schaut dich skeptisch an* Mama sagt, Flunkern ist doof.“`,feedback:`Ein Bluff mit falscher Analogie und der Ausrede „Das lernst du später“. Es ist besser, die Grenze des eigenen Wissens zuzugeben als sie zu überspielen.`,score:-1},{text:`„Das weiß ich ehrlich nicht. Blaues Licht hat kürzere Wellen, die streut die Luft stärker. Warum, weiß ich nicht. Wie finden wir's raus?“`,style:`sokratisch`,reaction:`„*strahlt* Du weißt es auch nicht? Dann sind wir zusammen Forscher! Wir fragen Opa! Oder die Bibliothek! Oder wir machen ein Experiment!“`,feedback:`Ehrlich bleiben und gemeinsam suchen: Die Grenze des Wissens benennen und sie in ein Forschungsprojekt verwandeln, statt zu bluffen. Das lernt Emma nebenbei als Haltung.`,score:3,nextStepId:`step-3`},{text:`„Jetzt hat mich die Warum-Maschine erwischt! Mein Wissen reicht bis zur Luft, danach wird es nebelig. Wer in der Familie weiß noch mehr als ich, Emma?“`,style:`humorvoll`,reaction:`„Opa! Der weiß alles! *überlegt* Oder auch nicht ... Dann fragen wir ihn zusammen, und wenn er's nicht weiß, fragen wir die Bibliothek!“`,feedback:`Ehrlich und lustig: Du gibst die Grenze zu, ohne die Neugier zu bremsen. Ein kleiner Verweis auf Opa, aber noch kein gemeinsamer Plan.`,score:2,nextStepId:`step-3`}]},"step-3":{id:`step-3`,speaker:`Emma`,speech:`*kramt in ihrem Rucksack, hält triumphierend eine Taschenlampe hoch* „Ich hab eine Taschenlampe! Kann man damit was rausfinden?“`,options:[{text:`„Dann machen wir ein Experiment: Taschenlampe, Glas Wasser, ein Tropfen Milch, und wir leuchten durch. Forscherin Emma, bist du dabei?“`,style:`humorvoll`,reaction:`„*salutiert* Ja! Aber nur, wenn ich das Protokoll schreiben darf! Und wenn's blau wird, sagst du ‚Emma hatte recht‘!“`,feedback:`Aus dem „Ich weiß nicht“ wird ein überprüfbarer Versuch: Im Milchwasser erscheint das seitlich gestreute Licht bläulich, das durchscheinende eher rötlich, ähnlich wie beim Abendrot. Die Neugier wird belohnt.`,score:3},{text:`„Gute Idee! Wir fragen in der Bibliothek, und ich suche morgen ein Kinderbuch über den Himmel, das lesen wir dann zusammen. Abgemacht, Emma?“`,style:`deeskalierend`,reaction:`„Abgemacht! *schüttelt feierlich deine Hand* Aber nur, wenn es Bilder hat. Und wenn die Bibliothek es nicht weiß, fragen wir die Bibliothekarin!“`,feedback:`Gutes zweitbestes Ende: Du suchst gemeinsam weiter und hältst die Neugier am Leben, nur das Experiment mit eigenen Augen fehlt.`,score:1},{text:`„Genug gefragt für heute, Forscherin! Sonst platzt mir der Kopf. Wir gehen jetzt ein Eis kaufen, und morgen ist wieder ein neuer Tag, versprochen.“`,style:`ausstieg`,reaction:`„Aber ich hab noch zwölf Warums! *seufzt, dann hellt sich ihr Blick auf* ... Mit Streuseln?“`,feedback:`Verständlich, aber du schiebst die Neugier ab, statt sie zu nutzen. Das Eis rettet die Stimmung, die Chance zum gemeinsamen Entdecken ist vertan.`,score:-1}]},"step-bluff":{id:`step-bluff`,speaker:`Emma`,speech:`„Ich frag jetzt Mama. Die sagt immer, wenn man was nicht weiß, sagt man's. *geht beleidigt zur Parkbank*“`,options:[{text:`Szenario beendet: Dein Bluff ist aufgeflogen, und Emma hat gelernt, dass Erwachsene auch mal flunkern.`,style:`ausstieg`,reaction:`Kinder merken Widersprüche und Bluffs schneller, als wir denken.`,feedback:`Probiere es beim nächsten Mal mit: „Das weiß ich nicht, wie finden wir es heraus?“`,score:0}]}}},{id:`scen-kommentarspalte`,title:`Kommentarspalte: „Beweis mir das Gegenteil!“`,subtitle:`Beweislast, „Wach auf“-Rhetorik & Street Epistemology (A.4, G.1.1, H.2.2)`,character:`Durchblick_77`,avatar:`🕶️`,context:`Unter einem Zeitungsartikel, der erklärt, dass Globuli über den Placeboeffekt hinaus nicht wirken, hat sich „Durchblick_77“ auf deinen Kommentar gestürzt. Er ist geistreich, schnell und liebt spitze Pointen. Du tippst deine Antworten, und die Spalte liest mit.`,goal:`Widerstehe der Versuchung, zurückzustechen. Halte deine Antworten witzig, aber freundlich und sachlich, und führe das Gespräch von „Beweis mir das Gegenteil!“ zu einer Frage, wie man überhaupt prüfen kann.`,bereich:`Online`,laenge:`mittel`,ton:`sarkastisch`,bestehenAb:9,lektion:`Wer in der Kommentarspalte zurückspottet, spielt das „Wach auf“-Spiel mit: Er liefert genau das Bild, das der andere von „den Besserwissern“ hat. Sachlich bleibt, wer die Beweislast freundlich zurückspielt (A.4), nach dem Prüfverfahren fragt (A.3) und die Pointe für Gelegenheiten aufhebt, in denen sie den Menschen nicht trifft. Ein Gespräch gewinnt man nicht, man öffnet oder schließt es.`,toolRef:`A.4, A.3, A.5, G.1.1, G.2.4, H.2.1, H.2.2`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Durchblick_77`,speech:`„Ach, wieder so ein Studierter, der Globuli für Zuckerkugeln hält. Beweis mir das Gegenteil! Meine Tochter hatte als Baby Ohrenschmerzen, Globuli rein, Ruhe. Aber klar, ein Skandal, wie gefährlich Zucker ist. Wach auf!“`,options:[{text:`„Aufwachen kann ich gern, sobald du mir erklärst, wie ein Mittel wirkt, von dem in den üblichen Hochpotenzen rechnerisch kein einziges Molekül übrig ist. Zucker ist da wenigstens ein ehrlicher Rohstoff.“`,style:`sarkastisch`,reaction:`„Ha, getroffen! Wenn den Fachleuten die Argumente ausgehen, kommt der Spott. Und Beweis mir das Gegenteil – das kam hier noch nicht.“`,feedback:`Verführerisch, weil der Spruch sitzt. Aber du zahlst mit Spott zurück und bestätigst sein Bild vom überheblichen Besserwisser (G.1.1). Er sammelt Punkte, du verlierst das Gespräch.`,score:-2,nextStepId:`step-spott`},{text:`„Dass es deiner Tochter besser ging, freut mich, und das nehme ich ernst. Erzähl mal: Wie lange hatte sie die Schmerzen, wann hast du die Kügelchen gegeben, und was hat sich danach verändert?“`,style:`sokratisch`,reaction:`„*tippt schneller* Na also, mal einer, der fragt statt zu belehren. Sie war acht Monate alt, Ohrenschmerzen, Nacht für Nacht, und der Arzt sagte nur: abwarten.“`,feedback:`Gelungen: Du wertest die Geschichte auf, statt sie anzugreifen, und fragst nach seiner Erfahrung statt nach seiner Schuld. Die Beweislast-Falle („Beweis mir das Gegenteil!“, A.4) bleibt unbeantwortet und trotzdem friedlich.`,score:3,nextStepId:`step-2`},{text:`„Okay, ich bin kein Arzt, und für deine Tochter hat es offenbar gepasst. Jeder, wie er mag. Ich wünsche euch weiterhin alles Gute und ruhige Nächte, und lassen wir es hier einfach gut sein.“`,style:`ausstieg`,reaction:`„Siehst du, Leute, das Schlafschaf gibt klein bei! Ich wusste, ihr habt nichts in der Hand. Wach auf, Kommentarspalte!“`,feedback:`Das ist Kapitulation, kein Ausstieg im Sinn von H.2.4: Du verlässt das Gespräch nicht ruhig, sondern gibst ihm den Sieg und seine Sicht der Dinge.`,score:-1,nextStepId:`step-fail`}]},"step-spott":{id:`step-spott`,speaker:`Durchblick_77`,speech:`„Hab ich dir den Zahn gezogen? Der Spott kommt immer, wenn's eng wird. Also, Beweis mir das Gegenteil, oder war 'Zuckerkugel' schon dein ganzes Pulver?“`,options:[{text:`„Ich habe die Schwäche der Argumente zuerst mit Spott ersetzt, das war ein Fehler. Neustart: Das mit deiner Tochter interessiert mich ehrlich: Was war damals bei den Ohrenschmerzen genau los?“`,style:`deeskalierend`,reaction:`„*tippt langsam* Oha, eine Entschuldigung in der Kommentarspalte, das ist fast Weltkulturerbe. Na gut: Acht Monate alt, Ohrenschmerzen, der Arzt sagte abwarten.“`,feedback:`Du räumst den Fehler ein und öffnest die Tür wieder. Das senkt die Temperatur, ohne dass du in der Sache nachgibst (H.2.1).`,score:1,nextStepId:`step-2`},{text:`„Nach der Beweislast muss derjenige belegen, der eine Wirkung behauptet, nicht der, der sie bezweifelt. „Beweis mir das Gegenteil“ funktioniert logisch nicht, so läuft Beweisführung nun mal nicht.“`,style:`frontal`,reaction:`„Beweislast, Beweislast! Klingt nach Amt mit Wartenummer. Gut, hier meine 'Anekdote', und die ist besser als dein Paragrafenreiten.“`,feedback:`Inhaltlich stimmt es (A.4), aber der Lehrsatz kommt als Vorlesung und klingt nach Ausweichen. Er hört: „Ich muss nicht antworten.“ Das Gespräch geht weiter, aber auf Kosten von Vertrauen.`,score:0,nextStepId:`step-2`},{text:`„Ich habe ja nur gefragt, ob Zucker Wunder wirkt. Deine Geschichte kann ich ohnehin nicht widerlegen, und dein Publikum applaudiert so schön. Viel Spaß mit den Kügelchen!“`,style:`sarkastisch`,reaction:`„Haha, der Rückzug mit Sahnehäubchen! Lies dir mal deine eigenen Kommentare durch, du hast dich selbst widerlegt. Wieder ein Aufgewachter weniger, haha.“`,feedback:`Spott, der zweite Streich: Sarkasmus auf Kosten des Gegenübers plus Abgang. Er spielt dem „Wach auf“-Spiel in die Hände, die Spalte sieht nur den abtauchenden Besserwisser.`,score:-2,nextStepId:`step-fail`}]},"step-2":{id:`step-2`,speaker:`Durchblick_77`,speech:`„Nacht für Nacht dieses Geschrei! Der Arzt meinte, abwarten. Wir haben Globuli gegeben, und am nächsten Morgen war Ruhe. Das ist kein Zufall, das ist Erfahrung, und dagegen kommst du mit deinen Studien nicht an.“`,options:[{text:`„Das klingt nach einer ziemlich anstrengenden Zeit, schön, dass es besser wurde. Mich interessiert: Woran hättest du denn erkannt, dass es auch ganz ohne Kügelchen von allein abgeklungen wäre?“`,style:`sokratisch`,reaction:`„*tippt langsam* Hm. Der Arzt hat tatsächlich gesagt, das gehe oft von selbst weg. Aber woran erkennt man das, wenn man's nie probiert hat?“`,feedback:`Sehr gut: Du stellst die Kernfrage von Korrelation und Kausalität (A.5) als ehrliche Neugier. Er muss selbst auf die Lücke blicken, du musstest kein Fachwort dazu aussprechen.`,score:3,nextStepId:`step-3`},{text:`„Die Hahn-Logik, ich liebe sie: Der Hahn kräht, die Sonne geht auf, also ist er der Chef. Mein Nachbar lässt seinen deshalb nie ausschlafen, man weiß ja nie. Hauptsache, er kräht rechtzeitig genug.“`,style:`sarkastisch`,reaction:`„Sehr witzig, ein Gockel bin ich also. Dann sag doch gleich, wo dein Beweis bleibt, und erzähl mir nicht, es sei ja nur ein Hahn.“`,feedback:`Der Hahn-Vergleich ist geistreich und trifft den Denkfehler (post hoc), aber er kommt als Stich: Er hört „Gockel“. Die Pointe war gut, das Ziel war falsch, denn witzig bleibt man nur, wenn man den Menschen schont.`,score:-1,nextStepId:`step-3`},{text:`„Das nennt man den Post-hoc-Fehlschluss, mit einem Schuss Regression zur Mitte. Ohrenschmerzen vergehen häufig von selbst, und dass die Kügelchen genau dann kamen, kann reiner Zufall sein.“`,style:`frontal`,reaction:`„Fachlatein! Ich hab mein Kind nachts im Arm gehabt, du bringst mir Fachwörter. Da gibt es nichts mehr zu reden, du hörst mir sowieso nicht zu.“`,feedback:`Fachlich korrekt, aber als Urteil über eine Mutter, die nachts am Bett saß. Wer die Erfahrung eines Menschen mit einem Etikett (post hoc) abtut, wird nicht mehr gehört (H.2.3).`,score:-2,nextStepId:`step-fail`}]},"step-3":{id:`step-3`,speaker:`Durchblick_77`,speech:`„Studien, Studien! Wer bezahlt die denn? Die, die an Chemie verdienen. Warum soll ich denen mehr glauben als meinen eigenen Augen? Wach auf, Freundchen!“`,options:[{text:`„Deinen Augen vertraue ich auch. Wie wäre ein Test, dem beide trauen können: Kügelchen mit und ohne Wirkstoff, keiner weiß, wer welche bekommt? Würdest du dem Ergebnis auch bei einem Nein glauben?“`,style:`sokratisch`,reaction:`„Hm. Wenn keiner weiß, wer was kriegt, kann auch keiner schummeln, das hat was. Ob ich das Ergebnis hinnehme, wenn's gegen mich ausgeht, muss ich mir überlegen.“`,feedback:`Meisterhaft: Du bietest ein Verfahren, das beiden Seiten gerecht wird, und fragst nach der Bedingung für Umdenken (A.3, Falsifizierbarkeit). Ehrliche Antwort: Er muss sich festlegen, ohne dass du ihn drängst.`,score:3,nextStepId:`step-4`},{text:`„Verdient wird auch an Kügelchen, die Hersteller sind Firmen mit Umsatz und keine Wohlfahrtsvereine. Aber Kasse gegen Kasse zählen bringt uns nicht weiter. Was würde dich denn überzeugen?“`,style:`sokratisch`,reaction:`„Hm, Firmen sind Firmen, da hast du recht. Was mich überzeugt? Dass es meinem Kind half. Aber ein Test, den auch Skeptiker anerkennen, wäre mal was Neues.“`,feedback:`Gut: Der Hinweis auf die Interessen beider Seiten entschärft das Pharma-Feindbild (G.2.4), ohne ihn zu beschämen. Die Schlussfrage wirkt aber vorsichtiger, als sie sein könnte, daher nur zweitbester Weg.`,score:1,nextStepId:`step-4`},{text:`„Eigene Augen, na klar. Dieselben, die auch Gesichter im Toast und Tiere in den Wolken sehen. Bravo, die Optik stimmt bestimmt, nur der Befund leider nicht, und den klärt ein Test, nicht das Bauchgefühl.“`,style:`sarkastisch`,reaction:`„Ah, jetzt wird's persönlich! Klar, wer anders denkt, ist blind, das kennt man von euch. Gespräch beendet, ich lass mich nicht beleidigen!“`,feedback:`Das ist geistreich und verführerisch, aber es ist Sarkasmus auf Kosten des Menschen: Seziert wird die Behauptung, nicht der Mensch. Er hört nur „blind“ und macht die Tür zu.`,score:-2,nextStepId:`step-fail`}]},"step-4":{id:`step-4`,speaker:`Durchblick_77`,speech:`„Ein Blindtest also. Gibt's sowas schon? Und sag jetzt nicht, ,Ja, und die sagen alle dasselbe', sonst glaub ich dir erst recht nichts.“`,options:[{text:`„Ja, die gibt es, und gut gemacht zeigen sie keinen Effekt über Placebo hinaus. Ich schicke dir Quellen zum Selbstprüfen. Bei Ohrenschmerzen eines Kindes bleibt der Kinderarzt die erste Adresse.“`,style:`sokratisch`,reaction:`„Die schwächste raussuchen, das ist fies fair. Gut, schick sie rüber. Und falls die Kügelchen durchfallen, schuldest du mir ein Foto von deinem Zuckerstreuer.“`,feedback:`Sehr gut: Du antwortest ehrlich auf die Sachfrage, gibst ihm Quellen und das Prüfrecht, und der Hinweis auf ärztliche Abklärung ist kein Rückzieher, sondern Verantwortung. Beweislast und Gesichtswahrung gelingen beide (A.4, H.2.2).`,score:3},{text:`„Die gibt es, und dein ,alle sagen dasselbe' ist ein bequemer Notausgang. Such dir die Studie raus, die du am wenigsten leiden kannst, und wir nehmen sie gemeinsam auseinander.“`,style:`humorvoll`,reaction:`„*tippt* Ha, der Notausgang, erwischt. Mal sehen, ob deine Studien halten, was du versprichst. Ich lese rein, aber ich sag dir gleich, ich bin schwer zu überzeugen.“`,feedback:`Humor, der verbindet: Du nimmst ihm den „alle sagen dasselbe“-Trick freundlich weg und lässt die Tür offen. Etwas kürzer in der Sache als die beste Antwort, daher eine gute zweite Wahl.`,score:2},{text:`„Ich merke schon, hier wird niemand mehr wach. Mach's gut und grüß deine Kügelchen von mir, ich habe noch einen Termin mit der Realität. Viel Spaß beim Träumen!“`,style:`sarkastisch`,reaction:`„Der Termin mit der Realität, genau solche Sprüche meine ich! Ihr haltet euch für was Besseres. Tschüss, und viel Spaß mit euren Pharma-Märchen!“`,feedback:`Du hast alles bis hierher richtig gemacht und verspielst es im letzten Satz: Der Abgang ist ein Spott, der seine Überzeugung nur festigt. Eine gute Pointe ist keine Brücke.`,score:-1}]},"step-fail":{id:`step-fail`,speaker:`Durchblick_77`,speech:`„Na also. Wieder einer, der abtaucht, wenn's ernst wird. Kommentarspalte, seht her: Wach auf, Leute!“ *drei Daumen hoch von Fremden*`,options:[{text:`Szenario beendet: Du hast die Kommentarspalte verloren, weil du auf Pointen statt auf den Menschen geantwortet hast.`,style:`ausstieg`,reaction:`Beim nächsten Mal: Erst Neugier, dann Frage, dann (wenn überhaupt) Pointe.`,feedback:`Reflektiere: Wem hilft ein Sieg in der Kommentarspalte, wenn der Mensch dahinter nie wieder zuhört?`,score:0}]}}},{id:`scen-gartenzaun-mond`,title:`Am Gartenzaun: Pflanzen nach dem Mond`,subtitle:`Mondglaube, Falsifizierbarkeit & Bestätigungsfehler (A.3, B.1, B.9)`,character:`Herr Wendt`,avatar:`🌕`,context:`Dein Nachbar Herr Wendt, 74, pflanzt seit jeher streng nach den Mondphasen und hat dich gerade am Gartenzaun gestoppt, weil du Salat setzen willst. Nebenbei warnt er, bei Vollmond passierten mehr Unfälle. Du magst ihn, und sein Garten ist der schönste der Straße.`,goal:`Bleibe freundlich, würdige sein Erbe und seinen Garten, und lenke das Gespräch von „Das ist so“ zu der Frage, wie man es gemeinsam prüfen kann.`,bereich:`Nachbarschaft`,laenge:`mittel`,ton:`heiter`,bestehenAb:9,lektion:`Wer einen liebgewonnenen Brauch angreift, trifft den Menschen und seine Geschichte. Ein Kompliment, eine ehrliche Frage und eine Wette (A.3) machen aus dem Streit ein Spiel, und der Hinweis auf selektive Erinnerung (B.1, B.9) kommt als Einladung statt als Urteil. Auch Wendt darf recht behalten, sofern das Beet es sagt.`,toolRef:`A.3, A.5, B.1, B.3, B.9, H.2.2`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Herr Wendt`,speech:`„Halt, Nachbar, nicht heute pflanzen! Abnehmender Mond, Wurzeltag, da wird der Salat nix. Mein Opa hat es so gemacht, und der wurde 91! Und heute Abend ist Vollmond, da knallt es auf der Straße wie sonst nie.“`,options:[{text:`„Herr Wendt, der Mond hat auf Ihren Salat so viel Einfluss wie die Gießkanne auf den Wetterbericht. Das ist längst widerlegt, und auch die Vollmond-Unfälle sind ein bloßer Mythos, den man sich merkt.“`,style:`frontal`,reaction:`„Widerlegt, widerlegt! Der Mond steuert das Meer, aber meinen Salat nicht? Sie haben noch nie eine Möhre gezogen, Nachbar. Gehen Sie, ich habe zu tun.“`,feedback:`Faktisch richtig, aber als Totschlag: Für Wendt ist der Mondkalender Opas Erbe und Stolz. Wer das Erbe angreift, greift den Mann an (B.4, Zugehörigkeit).`,score:-2,nextStepId:`step-fail`},{text:`„Dann sagen Sie dem Mond bitte, er soll meine Schnecken gleich mit abräumen. Aber mal ehrlich, Ihr Salat ist der schönste der Straße. Erzählen Sie mal, wann setzen Sie was, und warum gerade dann?“`,style:`humorvoll`,reaction:`„*lacht* Die Schnecken, ja, die nehmen auch bei Vollmond keinen Urlaub! Also: Salat bei zunehmendem Mond, Wurzelgemüse bei abnehmendem. Das ist alles Gesetz, Nachbar.“`,feedback:`Gute Wahl: Humor, der verbindet, plus ein ehrliches Kompliment. Er lacht mit dir, die Tür bleibt offen. Nur der Weg zur Prüfung fehlt noch.`,score:2,nextStepId:`step-2`},{text:`„Ihr Salat ist der schönste der Straße, das sieht jeder. Wie haben Sie gemerkt, dass der nach Mond gesäte besser wird als einer, den Sie an einem ,falschen' Tag gesetzt haben?“`,style:`sokratisch`,reaction:`„Wie ich das gemerkt habe? *kratzt sich am Kinn* Na, mein Lebtag! Letztes Jahr, Möhren an einem schlechten Tag: lauter Gabeln, lauter Beine! Da sah man's doch!“`,feedback:`Sehr gut: Kompliment, dann eine echte Frage nach seiner Beobachtung (H.2.2). Er erzählt dir sein „Beweisstück“, statt sich zu verteidigen.`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Herr Wendt`,speech:`„Und in der Notaufnahme erst, sagt meine Schwägerin, die ist Krankenschwester: Bei Vollmond ist die Hölle los! Das kann doch kein Zufall sein. Ich bin ja nicht von gestern, Nachbar!“`,options:[{text:`„Gabelmöhren, ärgerlich! Wollen wir das mal richtig prüfen? Beet teilen, eine Hälfte nach Mond, eine ohne Kalender, gleiche Erde, und im Herbst zählen wir beide Ernten. Würde Sie das reizen?“`,style:`sokratisch`,reaction:`„Ein Wettstreit, Mond gegen Nachbar? *reibt die Hände* Das ist ein Vorschlag nach meinem Geschmack. Aber ich sage Ihnen gleich: Wenn Mond gewinnt, hören Sie auf zu lachen!“`,feedback:`Meisterhaft: Du machst aus dem Streit ein gemeinsames Experiment (A.3). Er will gewinnen, aber nach Regeln, die vorher feststehen. Falsifizierbarkeit als Spiel.`,score:3,nextStepId:`step-3`},{text:`„Möhren gabeln, wenn sie auf Steine oder frisch gedüngte, klumpige Erde treffen, und das passiert an jedem Tag im Mondkalender. Mit Notaufnahmen ist es ähnlich: Man merkt sich die wilden Nächte.“`,style:`frontal`,reaction:`„Steine hab ich, da haben Sie recht... aber so einfach ist es nicht! Und die Notaufnahme kennen Sie nicht, Nachbar. Meine Schwägerin hat 30 Jahre Schicht!“`,feedback:`Richtig und freundlich vorgetragen, aber zwei Erklärungen auf einmal und ein Lehrvortrag. Er wehrt sich mit dem Hinweis auf die Erfahrung seiner Schwägerin und hört nur halb zu (B.1, B.9).`,score:0,nextStepId:`step-3`},{text:`„Wissen Sie was, Sie haben den Garten, ich nur Topfbasilikum. Wenn Sie sagen, heute Abend ist Vollmond und Gefahr, dann bleibe ich lieber zu Hause. Sicher ist sicher.“`,style:`ausstieg`,reaction:`„Na also, Sie sind ein vernünftiger Mann! Vollmond ist nichts für Leichtsinnige. Und wehe, Sie pflanzen vor Donnerstag, dann ist der Salat dahin!“`,feedback:`Kapitulation: Du bestätigst einen Mythos, um Frieden zu haben. Harmlos wirkt das, aber du hast die Gelegenheit verschenkt, gemeinsam nachzuschauen (H.2.4).`,score:-1,nextStepId:`step-gebeugt`}]},"step-3":{id:`step-3`,speaker:`Herr Wendt`,speech:`„Zwei Beete also. Aber wenn mein Mond-Beet verliert, war es bestimmt der Boden! *grinst* Und wenn es gewinnt, hören Sie auf zu lachen, Nachbar, abgemacht?“`,options:[{text:`„Dafür machen wir es vorher aus: Was müsste im Herbst auf der Waage stehen, damit Sie sagen: ,Okay, der Mond bringt nichts'? Und was für mich: ,Er bringt was'? Wir schreiben beides an den Zaun.“`,style:`sokratisch`,reaction:`„*lacht laut* An den Zaun schreiben! Gut, wir schreiben es mit Kreide an den Zaun, und wer verliert, kocht den Möhreneintopf. Sie sind mir ein listiger Nachbar.“`,feedback:`Meisterhaft: Du legst vorher fest, was als Widerlegung zählt (A.3, Falsifizierbarkeit), ohne ihn vorzuführen. Der Spaß am Wetten trägt die Prüfung.`,score:3,nextStepId:`step-4`},{text:`„Abgemacht, und der Verlierer bringt dem anderen einen Korb Möhren, egal wie sie gabeln. Aber den Boden prüfen wir fair mit: gleiche Erde, gleiche Gießkanne, beide Beethälften, kein Mogeln mit Dünger.“`,style:`humorvoll`,reaction:`„Ein Korb Möhren, in Ordnung! *schlägt über den Zaun ein* Aber ich habe die bessere Erde, das sehen Sie noch.“`,feedback:`Gut gelöst: Wette und Fairness im Scherz verpackt. Etwas weniger genau als die beste Antwort, weil nicht festgelegt ist, was als Ergebnis zählt, aber der Ton stimmt.`,score:2,nextStepId:`step-4`},{text:`„Klar, gewinnt der Mond, war es der Mond, verliert er, war es der Boden. Kopf gewinnt, Zahl verliert, ein sehr gemütliches Spiel für den Mond, wenn er nie verlieren kann.“`,style:`sarkastisch`,reaction:`„*hebt eine Augenbraue* Heute scharf, Nachbar! Na, dann ist der Boden eben gleich, und wir sehen, wer zuerst Kreide braucht. Aber das mit dem Kopf-Zahl merke ich mir.“`,feedback:`Geistreich und im Kern treffend, aber der Stich trifft seinen Stolz. Wendt lacht noch, doch du hast ihm den Eindruck gegeben, ihn durchschaut und vorgeführt zu haben.`,score:-1,nextStepId:`step-4`}]},"step-4":{id:`step-4`,speaker:`Herr Wendt`,speech:`„Gut, gut, wir probieren es. *spuckt in die Hand* Aber den Vollmond lasse ich mir nicht nehmen. Meine Schwägerin weiß, was sie sieht, und die lügt nicht!“`,options:[{text:`„Lügen tut sie sicher nicht. Erinnerung ist aber ein Gast mit Lieblingsfarbe: Wilde Vollmondnächte merkt man sich, ruhige nicht. Fragen wir sie, ob sie je beide gezählt hat, bei einem Bier im Garten.“`,style:`sokratisch`,reaction:`„Ob sie je beide gezählt hat... *lacht* Sie sind ein Schlitzohr. Gut, ich frage sie, und das Bier geht auf mich. Aber wenn sie 'Ja' sagt, haben Sie verloren!“`,feedback:`Sehr gut: Du greifst die Schwägerin nicht an, sondern lädst zum gemeinsamen Zählen ein. Erinnerung ist selektiv (B.1, B.9, B.3), und er findet das selbst heraus.`,score:3},{text:`„Beim Vollmond lasse ich Ihnen den Frieden, Herr Wendt. Ich wünsche Ihnen eine ruhige Nacht und mir einen schönen Salat im Herbst. Und die Wette steht, egal, was der Mond sagt.“`,style:`deeskalierend`,reaction:`„Der Frieden hält, Nachbar. Und die Wette auch. Aber bei Vollmond bleiben Sie mal brav auf dem Sofa, ich sag's nur zu Ihrem Besten.“`,feedback:`Der Frieden bleibt, die Wette bleibt, aber der Mythos auch. Für den Nachbarn ist das in Ordnung. Zweitbester Weg: Nur die Gartenfrage wird geprüft, die Unfall-Behauptung nicht.`,score:1},{text:`„Zu den Unfällen: Das ist schlicht falsch, Studien finden bei Vollmond keinen verlässlichen Anstieg. Da müssen Sie Ihre Schwägerin gar nicht erst fragen, glauben Sie mir.“`,style:`frontal`,reaction:`„Studien! Ihr mit euren Studien. Heute Abend sehen wir, wer recht hat, Nachbar. Und wenn auf der Straße was passiert, sage ich nichts, aber ich denke es.“`,feedback:`Wieder ein Faktum als Schlussstrich: Er hört „Ihre Schwägerin ist dumm“. Aus der freundlichen Wette wird ein Streit über Recht und Unrecht.`,score:-1}]},"step-fail":{id:`step-fail`,speaker:`Herr Wendt`,speech:`„Sie haben noch nie einen Garten geführt, das merkt man. Ich lasse mir von keinem Neuling den Mond ausreden. Schönen Abend noch.“ *dreht sich um und geht zur Gießkanne*`,options:[{text:`Szenario beendet: Herr Wendt hat sich in seinen Garten zurückgezogen, und der Mondkalender ist jetzt Ehrensache.`,style:`ausstieg`,reaction:`Beim nächsten Mal: Erst das Kompliment und die Frage, dann der Vorschlag.`,feedback:`Reflektiere: Wer ein Familienerbe verteidigen muss, hört keine Argumente mehr.`,score:0}]},"step-gebeugt":{id:`step-gebeugt`,speaker:`Herr Wendt`,speech:`„Da gibt's was, was die Wissenschaft nicht erklären kann, Nachbar, merken Sie sich das! Und Salat nie vor Donnerstag, sonst schießt er.“ *klopft zufrieden auf den Zaunpfosten*`,options:[{text:`Szenario beendet: Du hast den Frieden gewahrt, aber den Mondmythos gleich mit bestätigt.`,style:`ausstieg`,reaction:`Beim nächsten Mal: Neugier statt Zustimmung. Auch ein Zaun ist ein guter Ort für eine Frage.`,feedback:`Reflektiere: Wann hilft Zustimmen, und wann nimmt es dem anderen die Chance, selbst nachzuschauen?`,score:0}]}}},{id:`scen-elternabend-5g`,title:`Elternabend: Router im Klassenzimmer`,subtitle:`Angst vor Strahlung & Empathie-Matrix (H.1.6, H.2.1)`,character:`Kerstin`,avatar:`👩‍👧`,context:`Die Schule installiert ein neues WLAN, und Kerstin will auf dem Schulhof nach dem Elternabend Unterschriften gegen den Router sammeln. Ihre Tochter Lina hat seit zwei Wochen Kopfschmerzen, und Kerstin liest im Netz von Strahlung bei Kindern. Du bist Elternvertreter und sprichst sie an.`,goal:`Nimm die Angst ernst, ohne die Behauptung zu übernehmen. Führe das Gespräch von der Strahlung zu überprüfbaren Schritten, etwa Messung und Arztbesuch.`,bereich:`Schule`,laenge:`mittel`,ton:`ernst`,bestehenAb:9,lektion:`Hinter der Strahlungsangst steht die Sorge um ein Kind, und die lässt sich nicht wegerklären. Wer zuerst das Gefühl hört (H.1.6), dann gemeinsam fragt, was sich noch verändert hat (A.5), und die Sorge in überprüfbare Schritte übersetzt, öffnet ein Gespräch, das Fakten wirklich trägt. Kopfschmerzen bei Kindern gehören in jedem Fall ärztlich abgeklärt, unabhängig davon, was man vom Router hält.`,toolRef:`H.1.6, H.2.1, H.2.3, A.5, D.1.5`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Kerstin`,speech:`„Ich sage es ganz offen: Ich sammle Unterschriften gegen diesen Router. Lina hat seit zwei Wochen Kopfschmerzen, und jetzt hängt dieses Ding in ihrem Klassenraum. Ich lese überall, dass diese Strahlung Kinder krank macht. Das will ich für mein Kind nicht riskieren.“`,options:[{text:`„Kerstin, das ist nichtionisierende Strahlung weit unter den Grenzwerten, und sie ist gut untersucht. Es gibt keinen Grund zur Sorge, das kannst du ruhig nachlesen. Bitte lass es einfach gut sein, die Sache ist geklärt.“`,style:`frontal`,reaction:`„Bitte lass es einfach gut sein? Ich lese also zu viel, und du hast die Antworten, so läuft das hier. Ich sammle weiter Unterschriften, und zwar bei allen, die sich nicht abbügeln lassen!“`,feedback:`Faktisch richtig, aber du bügelst ihre Angst weg: Sie hört „Deine Sorge ist dumm“. Fakten erreichen niemanden, solange das Gefühl nicht gesehen wurde (H.1.6).`,score:-2,nextStepId:`step-fail`},{text:`„Kopfschmerzen bei einem Kind, das ist wirklich beunruhigend. Vielleicht sollten wir den Router erst einmal abschalten lassen, bis alles geklärt ist. Ich unterstütze deinen Antrag gern und sammle auch mit.“`,style:`affektiv`,reaction:`„Siehst du, du siehst es auch! Dann nehme ich Lina morgen aus dem Unterricht, bis das Ding ab ist. Wir sammeln gleich Unterschriften, und die Zeitung rufe ich auch an!“`,feedback:`Mitgefühl ohne Halt: Du übernimmst ihre Angst als Beschluss, statt sie zu verstehen. Mitgefühl und Handeln sind verschiedene Werkzeuge (H.1.6), und hier hast du beide verwechselt.`,score:-1,nextStepId:`step-panic`},{text:`„Ich merke, wie sehr dich das beschäftigt, und die Sorge um Lina ist das Normalste der Welt. Magst du mir erzählen, wann die Kopfschmerzen begannen und was dir an der Strahlung am meisten Angst macht?“`,style:`deeskalierend`,reaction:`„*atmet durch* Danke, dass du nicht gleich abwinkst. Es fing vor zwei Wochen an, meist nachmittags. Und der Router hängt, glaube ich, seit letzter Woche... *stockt kurz*“`,feedback:`Sehr gut: Du validierst das Gefühl, nicht die Behauptung (H.1.6), und fragst nach Konkretem. Sie beginnt von selbst, ihren Zeitablauf zu prüfen, ohne dass du sie korrigierst.`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Kerstin`,speech:`„Na ja, der Router ist neu. Aber im Internet steht, dass Kinder viel empfindlicher sind. Und die Grenzwerte hat doch die Industrie gemacht. Wem soll ich da glauben?“`,options:[{text:`„Gute Frage, wem man glaubt. Lass uns auf Lina schauen: Was hat sich bei ihr sonst verändert, Schlaf, Trinken, Bildschirmzeit, Mathearbeit? Und wäre es gut, die Kopfschmerzen mit der Kinderärztin abzuklären?“`,style:`sokratisch`,reaction:`„Schlaf... sie schläft schlecht, seit die Klassenarbeiten losgehen. Und getrunken hat sie auch wenig. Die Kinderärztin hatte ich noch nicht angerufen, das mache ich diese Woche.“`,feedback:`Meisterhaft: Du gibst ihr einen Rahmen zum eigenen Nachdenken (A.5, Korrelation vs. Kausalität) und führst zum richtigen Ort für Kopfschmerzen. Die Abklärung beim Arzt ist hier das Wichtigste, nicht der Router.`,score:3,nextStepId:`step-3`},{text:`„Die Grenzwerte setzen unabhängige Gremien fest, mit großem Sicherheitsabstand zu allem, was man nachweisen konnte. Das Argument, die Industrie habe sie gemacht, stimmt so nicht.“`,style:`frontal`,reaction:`„Unabhängige Gremien, aha. Das sagen die ja immer. Ich bin keine Expertin, aber ich bin die Mutter. Dass du mir sofort widersprichst, macht mich nicht ruhiger.“`,feedback:`Sachlich richtig und ruhig, aber es ist eine Belehrung vor dem Zuhören. Du widerlegst die Behauptung, bevor du ihr Motiv gehört hast (H.2.3), und bleibst bei einer Verteidigung stehen.`,score:0,nextStepId:`step-3`},{text:`„Wollen wir das nicht in Ruhe beim nächsten Elternabend mit der Schulleitung klären? Heute ist es schon spät, und alle wollen nach Hause. Das kriegen wir gemeinsam gelöst.“`,style:`ausstieg`,reaction:`„Immer wird vertagt! Wenn es ernst wird, wollen alle nach Hause. Gut, dann klären wir es eben ohne euch, bei den Eltern, die zuhören.“`,feedback:`Das ist ein Ausstieg ohne Anschluss (H.2.4): Er klingt nach Vertagung und Vermeidung. Eine Sorge, die man vertagt, wächst meist bis zum nächsten Termin.`,score:-1,nextStepId:`step-fail`}]},"step-3":{id:`step-3`,speaker:`Kerstin`,speech:`„Okay, Kopfschmerzen können wohl auch andere Gründe haben. Aber trotzdem: Vorsicht ist besser als Nachsicht. Warum kann man nicht einfach Kabel legen, wie früher? Was ist so schlimm daran, kein Risiko einzugehen?“`,options:[{text:`„Dein Wunsch nach Vorsicht ist berechtigt. Wollen wir den Schulträger bitten, die Feldstärke im Klassenraum messen und mit den Grenzwerten vergleichen zu lassen? Dann reden wir mit Zahlen.“`,style:`sokratisch`,reaction:`„Messen lassen... ja, das ist ein Gedanke. Wenn da schwarz auf weiß steht, wie wenig oder viel es ist, kann ich damit leben. Und wenn es zu viel ist, weiß ich es auch.“`,feedback:`Sehr gut: Du nimmst ihren Wunsch nach Vorsicht ernst und machst ihn überprüfbar, statt ihn zu bestreiten. Zahlen statt Meinungen: Sie kann selbst entscheiden, was sie danach glaubt.`,score:3,nextStepId:`step-4`},{text:`„Wir könnten beantragen, dass der Router nur im Unterricht läuft, mit Zeitschaltuhr, und dass Lina nicht direkt unter dem Gerät sitzt. Wäre das für den Anfang ein Weg, mit dem du leben könntest?“`,style:`deeskalierend`,reaction:`„Zeitschaltuhr, Platz weiter weg... das klingt vernünftig. Es ist zwar nicht das, was ich wollte, aber immerhin ein Anfang, und jemand hat mir zugehört.“`,feedback:`Ein praktischer Kompromiss, der ihr Autonomie gibt (H.2.1). Zweitbester Weg: Er beruhigt, aber er prüft ihre Befürchtung nicht, sondern bedient sie. Die Messung wäre ehrlicher.`,score:1,nextStepId:`step-4`},{text:`„Mal ganz sachlich: Ein Handy am Kopf strahlt beim Telefonieren in der Regel viel stärker als ein Router im Raum. Wenn dich das wirklich umtreibt, dürfte Lina auch kein Handy haben. Hat sie denn eins?“`,style:`frontal`,reaction:`„Jetzt bin ich auch noch eine schlechte Mutter, oder was? Darum geht es gerade nicht! Lina hat kein Handy, und genau deshalb soll es in der Schule auch nicht strahlen.“`,feedback:`Der Fakt stimmt, doch als Gegenfrage klingt er wie ein Vorwurf (Tu quoque, D.1.5). Du gewinnst den Punkt und verlierst ihr Vertrauen.`,score:-1,nextStepId:`step-4`}]},"step-4":{id:`step-4`,speaker:`Kerstin`,speech:`„Gut, meinetwegen. Aber wenn ich merke, dass es Lina schlechter geht, will ich, dass mir jemand zuhört. Und ich will nicht, dass man mich als Spinnerin abstempelt.“`,options:[{text:`„Du bist keine Spinnerin, du bist eine Mutter, die genau hinsieht. Wir bitten gemeinsam um die Messung, und Lina geht diese Woche zur Kinderärztin. Dann entscheiden wir mit Zahlen statt mit Angst.“`,style:`deeskalierend`,reaction:`„Danke. Ich hätte nicht gedacht, dass ich hier nach so einem Abend so ruhig gehe. Ich ruf morgen früh bei der Kinderärztin an, und das Schreiben machen wir zusammen.“`,feedback:`Mission gelungen: Du bestätigst ihre Würde, verbindest Messung und Arztbesuch und beendest das Gespräch mit einem gemeinsamen nächsten Schritt (H.1.6, H.2.1).`,score:3},{text:`„Dann kommt die Messung auf die Tagesordnung des nächsten Elternabends, und du stellst den Antrag selbst. So hast du es in der Hand, und niemand kann dich übergehen.“`,style:`deeskalierend`,reaction:`„Gut, das mache ich. Ich verlasse mich darauf, dass ihr mich dann auch ernst nehmt. Und ich rufe die Kinderärztin trotzdem an, bevor ich es vergesse.“`,feedback:`Solide: Du gibst ihr Handlungsspielraum und Respekt. Es fehlt der gemeinsame Schritt, daher klingt es mehr nach Abgabe als nach Zusammenarbeit.`,score:1},{text:`„Ich verstehe dich ja, aber die Mehrheit hat entschieden, und die Schule rüstet auf. Das Thema ist durch. Sei bitte nicht die Mutter, die den ganzen Elternabend spaltet.“`,style:`ausstieg`,reaction:`„Ich spalte also. Gut, dann gehe ich zum Schulamt, und das nächste Mal komme ich nicht allein. Du hast mir gerade gezeigt, dass es hier nicht ums Zuhören geht.“`,feedback:`Du hast bis hierher alles aufgebaut und beendest es mit einem Druckwort. Wer Sorgen als „Spaltung“ etikettiert, schafft die Fronten, die er vermeiden wollte.`,score:-1}]},"step-fail":{id:`step-fail`,speaker:`Kerstin`,speech:`„Ich habe meine Antwort. Ich gehe jetzt nach Hause und rufe die anderen Eltern an. Wer sich so abwimmeln lässt, ist selbst schuld.“ *geht mit schnellen Schritten zum Fahrradständer*`,options:[{text:`Szenario beendet: Kerstin fühlt sich nicht gehört und sammelt Unterschriften, ohne dass jemand ihre Angst ernst genommen hat.`,style:`ausstieg`,reaction:`Beim nächsten Mal: Erst das Gefühl hören, dann gemeinsam prüfen.`,feedback:`Reflektiere: Was hätte Kerstin gebraucht, um zuzuhören, bevor sie überzeugt werden konnte?`,score:0}]},"step-panic":{id:`step-panic`,speaker:`Kerstin`,speech:`„Wir sammeln noch heute Abend Unterschriften, und ich nehme Lina morgen aus dem Unterricht. Wer jetzt noch zögert, riskiert die Gesundheit unserer Kinder!“`,options:[{text:`Szenario beendet: Du hast die Angst bestätigt, statt Halt zu geben, und aus einer Sorge ist ein Aufruf geworden.`,style:`ausstieg`,reaction:`Mitgefühl braucht einen kühlen Kopf: erst verstehen, dann gemeinsam handeln.`,feedback:`Wende beim nächsten Mal die Empathie-Matrix an: Verstehen und Mitfühlen sind nicht Zustimmen (H.1.6).`,score:0}]}}},{id:`scen-kollege-ironie`,title:`Kollege Jonas und die Ironie`,subtitle:`Ironie als Schutzschild: Humor & Sokratisches Fragen (H.2.2)`,character:`Jonas`,avatar:`😏`,context:`In der Kaffeeküche läuft eine Meldung über eine neue Studie zum Schlaf. Dein Kollege Jonas kommentiert alles, was nach Wissenschaft klingt, mit einem Grinsen und einem Spruch. Du merkst, dass er sich hinter dem Witz verschanzt, und möchtest ihn trotzdem erreichen.`,goal:`Dringe durch, ohne seinen Witz zu zerstören: Lache mit, belohne ihn für Humor, der verbindet, und ziehe ihn mit einer echten Frage in ein Gespräch über Vertrauen und Prüfbarkeit.`,bereich:`Arbeit`,laenge:`mittel`,ton:`sarkastisch`,bestehenAb:8,lektion:`Ironie ist oft ein Schutzschild, kein Standpunkt. Wer sie angreift, trifft den Menschen, wer mitlacht und eine echte Frage stellt, öffnet die Tür. Die Sorge hinter dem Spruch („Man wird ja nur betrogen“) war berechtigt und ließ sich in Prüfkriterien verwandeln.`,toolRef:`H.2.2, H.1.3, D.3.7, A.2`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Jonas`,speech:`„Ach, die Wissenschaftler, die wissen ja alles. Sind ja alle gekauft, ne?“ *grinst über den Rand seiner Kaffeetasse, die Augenbraue schon im Anschlag*`,options:[{text:`„Alle gekauft? Das ist pauschaler Quatsch, Jonas. Wer so redet, kennt Studien nur von der Überschrift, nicht von innen. Komm, sei ernst.“`,style:`frontal`,reaction:`„Oha, der Herr Professor hat gesprochen. Ich hab nur einen Witz gemacht, aber bitte, ich nehm's zurück. Und mein Verstand gleich mit.“ *geht mit der Tasse*`,feedback:`Du behandelst den Witz als Behauptung und Jonas als Gegner. Er hat nun einen Grund mehr, nichts mehr ernst zu meinen (D.1.1: Angriff auf die Person statt Gespräch über die Sache).`,score:-2,nextStepId:`step-kalt`},{text:`„Klar, und dein Wissen stammt aus dem renommierten Fachjournal ‚Mein Cousin sagt‘, begutachtet vom Stammtisch. Stimmt's?“`,style:`sarkastisch`,reaction:`„Autsch, der saß. *hebt die Tasse wie bei einem Duell* Aber mein Cousin ist wenigstens nicht gekauft, der hat gar kein Geld.“`,feedback:`Der Konter ist witzig, geht aber auf Jonas' Kosten. Er antwortet mit der nächsten Pointe, und ihr duelliert euch, statt zu reden. Die Tür bleibt nur einen Spalt offen.`,score:-1,nextStepId:`step-kalt`},{text:`„Gekauft? Bei mir hat noch keiner angerufen, ich warte seit Jahren! Aber im Ernst: Woran erkennst du, welcher Studie man trauen kann?“`,style:`humorvoll`,reaction:`„*lacht* Mich hat auch noch keiner angerufen, schade! Ich dachte, ich bin hier der Komiker. Na ja, woran man's erkennt ... Ich sag mal: am Geldgeber. Wer zahlt, schafft an.“`,feedback:`Du gibst dem Witz Raum, lachst mit und stellst eine echte Frage, die ihn aus der Pose holt (H.2.2 Street Epistemology, H.1.3 Wohlwollen).`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Jonas`,speech:`„Das weiß doch jeder: Wer die Studie bezahlt, bestimmt das Ergebnis. Da kannst du lachen, wie du willst.“ *tippt sich vielsagend an die Tasse*`,options:[{text:`„Das ist ein genetischer Fehlschluss: Woher das Geld kommt, sagt nichts über die Richtigkeit. Prüfen musst du die Methode, nicht das Konto.“`,style:`frontal`,reaction:`„Genetischer Fehl-wie-bitte? Schon gut, Herr Lexikon. Ich glaub dir ja, dass du recht hast. Du hast ja auch das längere Wort.“`,feedback:`Inhaltlich richtig (D.3.7), aber als Fachbegriff-Keule serviert. Jonas flüchtet wieder in die Ironie, und das Argument kommt nicht an.`,score:0,nextStepId:`step-kalt`},{text:`„Stimmt, Geld kann verzerren, das gibt es wirklich. Wie müsste eine Studie gebaut sein, damit man dem Geldgeber auf die Finger schauen kann?“`,style:`sokratisch`,reaction:`„*zögert, die Pointe bleibt ihm kurz im Hals stecken* Na ... er müsste offenlegen, wer bezahlt hat. Und andere müssten nachrechnen können, sonst glaub ich nix.“`,feedback:`Du nimmst seine berechtigte Sorge ernst (H.1.3) und lässt ihn selbst die Prüfkriterien nennen, statt sie ihm vorzulesen. Das ist genau, was ein Skeptiker braucht.`,score:3,nextStepId:`step-3`},{text:`„Dann bin ich ja gespannt, wer meine Excel-Tabelle kauft. Gibt es bei dir überhaupt jemanden, den du für unbestechlich hältst, oder bist du der Einzige?“`,style:`humorvoll`,reaction:`„Ich? Unbestechlich? Für ein Stück Kuchen bin ich sofort zu haben. *grinst* Aber ehrlich: Ich hab nicht mal einen, dem ich alles glaube. Ist das schlimm?“`,feedback:`Der Humor bleibt warm, und die Frage lädt ihn zur Selbstauskunft ein. Etwas weniger zielgerichtet als eine Frage nach Prüfkriterien, aber die Tür steht weit offen.`,score:2,nextStepId:`step-3`}]},"step-3":{id:`step-3`,speaker:`Jonas`,speech:`„Offenlegen, nachrechnen, andere müssen es wiederholen ... klingt fast vernünftig. Aber wem soll ich dann glauben? Am Ende hat doch jeder irgendwo seine Finger drin.“`,options:[{text:`„Stimmt eigentlich, am Ende glaubt jeder, was zu ihm passt. Lassen wir's lieber, der Kaffee ist sowieso wichtiger als diese Debatte hier.“`,style:`ausstieg`,reaction:`„Wort des Tages! Prost auf den Kaffee.“ *wirkt ein bisschen enttäuscht, als hätte er sich auf mehr gefreut*`,feedback:`Kapitulation vor der Resignation: Du bestätigst genau das Achselzucken, das du aufbrechen wolltest („Man weiß ja eh nichts“, D.3.4 als gedankenstoppendes Klischee).`,score:-1},{text:`„Das frage ich mich auch oft. Wenn dein Ofen kaputt wäre: Würdest du dem Elektriker glauben, obwohl er bezahlt wird? Woran würdest du merken, ob er gut ist?“`,style:`sokratisch`,reaction:`„Dem Elektriker? Der kriegt ja Geld, klar. *überlegt* Ich glaube ihm, wenn der Ofen danach wieder läuft. Und wenn nicht, ruf ich ihn an. Hm.“`,feedback:`Eine Analogie aus seinem Alltag: Vertrauen ist nicht Alles-oder-nichts, sondern hängt an Überprüfbarkeit (A.2 Hierarchie der Evidenz). Du teilst seine Unsicherheit, statt ihn zu belehren.`,score:3,nextStepId:`step-4`},{text:`„Dann gib's zu: Du glaubst einfach, was dir passt. Das ist Bestätigungsfehler in Reinform, und das sollte dir endlich mal jemand sagen.“`,style:`frontal`,reaction:`„Ich hab Bestätigungsfehler? *lacht, aber nicht mehr mit den Augen* Jetzt wird's persönlich. Ich hole mir mal einen Keks.“`,feedback:`Du verwandelst seine ehrliche Frage in einen Vorwurf. Der Bestätigungsfehler (B.1) trifft alle, auch dich (B.29), und im Ton einer Anklage wird er zur Beleidigung.`,score:-2}]},"step-4":{id:`step-4`,speaker:`Jonas`,speech:`„*grinst, diesmal ohne Pose* Also, wenn ich's recht bedenke: Bei meinem Ofen prüfe ich, ob er heiß wird. Das ist ja irgendwie ... überprüfbar. Bei den Studien kann man das auch?“`,options:[{text:`„Siehst du, du bist gar nicht so skeptisch, nur wählerisch. Das ist schon fast Wissenschaft. Und ich nehme das Kompliment sofort zurück, wenn du's rumerzählst.“`,style:`humorvoll`,reaction:`„Wählerisch, das nehme ich als Titel. *hebt die Tasse* Zeigst du mir mal, wie man so was prüft? Aber nur, wenn's nicht trocken wird.“`,feedback:`Guter, warmer Abschluss: Du gibst ihm ein Etikett, das er behalten will, und bleibst im Ton. Es fehlt nur noch das konkrete Angebot.`,score:1},{text:`„Genau: Beim Ofen heißt es ‚wird er warm?‘, bei Studien ‚lässt sich's wiederholen?‘. Ich zeige dir morgen, wie man das prüft. Du bringst die Kekse.“`,style:`deeskalierend`,reaction:`„Abgemacht! Aber wenn's langweilig wird, nenne ich dich ab jetzt ‚Herr Doktor Ofen‘.“ *lacht, und diesmal meint er es freundlich*`,feedback:`Konkretes Angebot in seiner Sprache, mit Humor als Verbindung. Aus der Ironie wurde ein echtes Gespräch (H.2.1), ohne dass sein Witz verloren ging.`,score:3},{text:`„Na also, endlich vernünftig. Ich wusste, dass man dich mit Logik knacken kann. Merk dir das Gefühl, wenn du das nächste Mal alle über einen Kamm scherst.“`,style:`frontal`,reaction:`„Gewonnen, na toll. *verdreht die Augen* Dann bleib ich eben beim Ofen und du bei deinen Studien. Schönen Feierabend.“`,feedback:`Du hast recht behalten und die Beziehung verspielt. Wer das Siegerfoto braucht, bekommt die zugeklappte Tür dazu.`,score:-2}]},"step-kalt":{id:`step-kalt`,speaker:`Jonas`,speech:`„Weißt du was, ich glaub, wir sind beide zu klug für diese Küche. Ich geh mal wieder was Sinnvolles tun.“ *das Grinsen sitzt wie eine Rüstung*`,options:[{text:`Szenario beendet: Jonas ist hinter seiner Ironie verschwunden, und das Gespräch ist vorbei, bevor es begann.`,style:`ausstieg`,reaction:`Ironie ist oft Schutz, nicht Meinung: Wer sie angreift, trifft die Rüstung, nicht den Menschen.`,feedback:`Probiere es beim nächsten Mal mit Humor, der mitlacht, und einer echten Frage dahinter (H.2.2).`,score:0}]}}},{id:`scen-nachts-um-zwei`,title:`Nachts um zwei im Kaninchenbau`,subtitle:`Selbst-Autopsie: Bestätigungsfehler & Quellenprüfung (B.1, B.29)`,character:`Die Stimme im Kopf`,avatar:`🌙`,context:`Es ist 2 Uhr nachts, du scrollst im Bett und stößt auf einen Artikel, der deine Lieblingsmeinung perfekt bestätigt. Deine innere Stimme jubelt, schlägt vor, ihn sofort zu verschicken, und winkt jede Quellenfrage ab.`,goal:`Prüfe dich selbst, bevor du andere prüfst: Erkenne den Bestätigungsfehler, verfolge die Quelle zurück und suche den stärksten Gegenbeleg, ohne dich dafür zu beschimpfen.`,bereich:`Ich selbst`,laenge:`mittel`,ton:`ernst`,bestehenAb:8,lektion:`Je besser ein Beleg zu deiner Meinung passt, desto genauer solltest du hinsehen. Schlafmangel macht die Prüfung zusätzlich schwerer, deshalb gilt nachts: nichts verschicken, Quelle zurückverfolgen, Gegenbeleg suchen. Eine Meinung darf genauer werden, ohne zu sterben.`,toolRef:`B.1, B.29, A.2, A.10, B.27`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Die Stimme im Kopf`,speech:`*flüstert, es ist 2:07 Uhr, das Handydisplay leuchtet* „Na also! ‚Forscher bestätigen: Handschrift macht schlauer.‘ Hab ich immer gesagt. Quelle? Eine Uni wird genannt, das reicht doch. Schick den Link morgen früh an alle im Kurs!“`,options:[{text:`„Du hast so recht! Endlich der Beweis, den ich seit Jahren brauche. Ich schicke ihn sofort an alle los, bevor ich's am Ende wieder vergesse.“`,style:`affektiv`,reaction:`„Gesendet! *die Häkchen werden blau* ... Oh. Der Kursleiter hat zurückgeschrieben: ‚Welche Studie genau?‘ Gute Nacht, Schlaf.“`,feedback:`Das Gefühl der Bestätigung hat die Prüfung ersetzt (B.1 Bestätigungsfehler): Was perfekt passt, wird nicht gegengeprüft. Zu später Stunde besonders gefährlich.`,score:-1,nextStepId:`step-peinlich`},{text:`„Der Artikel passt verdächtig gut. Würde ich ihn auch feiern, wenn er das Gegenteil behauptete? Und woher stammt die Behauptung?“`,style:`sokratisch`,reaction:`„*gähnt* Unfair, ich bin müde und der Artikel hat Grafiken. Aber gut, die Frage ist nicht dumm. Wo steht denn die Studie?“`,feedback:`Der Prüfstein gegen den Bestätigungsfehler: Drehe die Frage um (B.1). Du richtest die Skepsis auf dich selbst statt auf andere (B.29), und das mitten in der Nacht.`,score:3,nextStepId:`step-2`},{text:`„Ich schaue morgen in Ruhe darauf, jetzt kommt das Handy weg. Wer nachts um zwei Beweise für seine Meinung sammelt, sammelt meist nur Zustimmung.“`,style:`ausstieg`,reaction:`„Na gut. Aber der Tab bleibt offen, und ich vergesse den Artikel nicht, nur damit du's weißt.“ *das Display dimmt sich, die Stimme grummelt*`,feedback:`Vernünftiger Rückzug: Du triffst keine Entscheidung im Schlafmangel. Es fehlt die Prüfung selbst, aber du hast den Impuls erkannt und gestoppt.`,score:1}]},"step-2":{id:`step-2`,speaker:`Die Stimme im Kopf`,speech:`„Die Überschrift nennt eine Uni, und die Grafiken sehen professionell aus. Außerdem: Dass sich etwas so richtig anfühlt, ist doch auch ein Indiz. Oder willst du mir jetzt mein Gefühl wegnehmen, mitten in der Nacht?“`,options:[{text:`„Kann ich nicht einfach mal glücklich sein, dass ich recht habe? Was soll's, dass ich müde bin, das ändert doch nichts am Inhalt.“`,style:`affektiv`,reaction:`„Genau, glücklich sein! *wohlig* Und die Quelle prüfen wir nie, so bleibt die Welt schön einfach. Gute Nacht, Wahrheit.“`,feedback:`Ein Gefühl der Gewissheit ist keine Evidenz (A.2): Schlafmangel schwächt die Urteilskraft, und genau deshalb ist 2 Uhr nachts der falsche Zeitpunkt für Gewissheit. Du verteidigst die Meinung, statt den Artikel zu prüfen.`,score:-2,nextStepId:`step-peinlich`},{text:`„Grafiken sind keine Quelle. Wo ist die Studie hinter der Uni-Überschrift, wer hat sie bezahlt, und wie wurde gemessen? Ich öffne die Originalseite.“`,style:`sokratisch`,reaction:`„*seufzt* Na schön, Detektiv. Die Seite ist ein Blog. Der verlinkt auf eine Zusammenfassung, die auf eine andere Zusammenfassung verlinkt. Das ist ... lang.“`,feedback:`Du gehst die Beweiskette rückwärts (A.2 Hierarchie der Evidenz): erst die Quelle, dann die Methode. Die Kette aus Zusammenfassungen ist ein typisches Warnsignal.`,score:3,nextStepId:`step-3`},{text:`„Dass sich etwas richtig anfühlt, sagt mein Magen auch über den Nachtsnack um zwei. Ich lese erst die Quelle und gratuliere mir danach, falls die Meinung hält.“`,style:`humorvoll`,reaction:`„Der Nachtsnack ist unfair, der fühlt sich wenigstens immer richtig an. *grummelt* Na gut, dann lass uns den Link verfolgen. Aber ich behalte mir das Gratulieren vor.“`,feedback:`Mit trockenem Humor entwaffnest du die innere Stimme, ohne sie zu bekämpfen. Weniger präzise als eine Prüffrage, aber die Prüfung beginnt.`,score:2,nextStepId:`step-3`}]},"step-3":{id:`step-3`,speaker:`Die Stimme im Kopf`,speech:`„*kleinlaut* Okay, die Quelle ist ein Blog, der eine Zusammenfassung einer Zusammenfassung verlinkt. Aber die Aussage stimmt doch trotzdem, oder? Es schreiben so viele darüber, da kann nicht alles falsch sein.“`,options:[{text:`„Viele Texte können auf einer einzigen Vermutung stehen. Was würde ich lesen, wenn ich nach dem Gegenteil suchte, und was wäre der stärkste Einwand?“`,style:`sokratisch`,reaction:`„*murrt* Der stärkste Einwand gegen mich selbst? Das ist gemein. Aber gut, ich tippe: ‚Handschrift vs. Tippen Studie Kritik‘.“`,feedback:`Das Stahlmann-Prinzip, auf dich selbst angewendet (A.10): Suche aktiv den besten Gegenbeleg. Das ist die Medizin gegen den Bestätigungsfehler (B.1), und viele Texte sind kein Beweis (B.27).`,score:3,nextStepId:`step-4`},{text:`„Blödsinn, nur weil viele abschreiben, wird es nicht wahr. Hör auf mit diesem Zirkus, das Ganze ist doch eh Unsinn und ich war ein Idiot.“`,style:`frontal`,reaction:`„Na bravo, jetzt bist du also ein Idiot. *die Stimme wird bissig* Und das nachts um zwei, bei einem Gehirn im Halbschlaf. Super Idee, alles über Bord zu werfen.“`,feedback:`Selbstbeschimpfung statt Selbstprüfung: Wer sich für den Irrtum abwertet, wird ihn beim nächsten Mal noch hartnäckiger verteidigen. Seziert wird die Behauptung, nicht der Mensch, auch nicht du selbst.`,score:-2,nextStepId:`step-peinlich`},{text:`„Vielleicht stimmt es teilweise. Ich merke es mir als offene Frage und suche morgen ausgeschlafen die Originalstudie, bevor ich irgendwem etwas schicke.“`,style:`deeskalierend`,reaction:`„Offene Frage, na gut. *die Stimme gähnt* Immerhin hast du nichts verschickt. Gute Nacht, Du.“`,feedback:`Solide, ruhige Lösung: Du vertagst die Prüfung auf den ausgeschlafenen Zustand. Du hast nicht geprüft, aber auch nichts verbreitet. Der Gegenbeleg fehlt noch.`,score:1}]},"step-4":{id:`step-4`,speaker:`Die Stimme im Kopf`,speech:`„*seufzt* Gegenteil suchen ... ‚Handschrift vs. Tippen Kritik‘. Hm. Hier steht, dass es auf die Aufgabe ankommt und dass manche Befunde umstritten sind. Das ruiniert meine Schlagzeile komplett.“`,options:[{text:`„Dann ist das alles Quatsch, und ich lag jahrelang falsch. Ich lösche jetzt alles, was ich je dazu gelesen habe, und glaube erst mal gar nichts mehr.“`,style:`affektiv`,reaction:`„Aha, ein Totalschaden. *trocken* Glückwunsch, du hast gerade eine Meinung durch eine Überreaktion ersetzt. Schlafen wir, bevor du das Haus noch abreißt.“`,feedback:`Überkorrektur ist die Schwester des Bestätigungsfehlers: Aus „alles stimmt“ wird „nichts stimmt“. Beides spart das genaue Hinsehen.`,score:-1},{text:`„Meine Meinung muss nicht sterben, nur genauer werden: ‚Handschrift kann bei manchen Aufgaben helfen.‘ Weniger Schlagzeile, aber haltbar.“`,style:`deeskalierend`,reaction:`„*schaltet das Licht aus* Das lässt sich verteidigen. Weniger Schlagzeile, mehr Wahrheit. Und jetzt schlaf, du Detektiv.“`,feedback:`Eine Überzeugung wird dem Beleg angepasst, nicht umgekehrt (A.3, A.7 Probabilistisches Denken): Du revidierst dosiert und bleibst handlungsfähig.`,score:3},{text:`„Gemischte Befunde heißt: Nicht widerlegt. Also bleibe ich bei meiner Meinung, mehr Zustimmung als Einwände gibt es ja auch, glaube ich. Gute Nacht.“`,style:`ausstieg`,reaction:`„Wie du meinst. *die Stimme zuckt mit den Schultern* Nur dass du's weißt: Morgen früh weißt du's besser, und dann reden wir noch mal.“`,feedback:`Du hast den Einwand gehört, aber nicht eingearbeitet: „Nicht widerlegt“ ist kein Beleg (B.11). Ein bequemer Kompromiss, der die Überzeugung nur stehen lässt.`,score:0}]},"step-peinlich":{id:`step-peinlich`,speaker:`Die Stimme im Kopf`,speech:`„Ich sag nur: 2:41 Uhr, und du hast gerade etwas getan, das dir morgen leidtun wird.“ *gähnt*`,options:[{text:`Szenario beendet: Die Gewissheit der Nacht hat die Prüfung der Quelle ersetzt, und der Morgen wird unangenehm.`,style:`ausstieg`,reaction:`Der Bestätigungsfehler (B.1) wirkt am stärksten, wenn man müde und überzeugt ist.`,feedback:`Beim nächsten Mal: Quelle prüfen, Gegenbeleg suchen, und Entscheidungen auf den Morgen verschieben.`,score:0}]}}},{id:`scen-freund-natron`,title:`Jonas und die Natron-Kur`,subtitle:`Bleiben, fragen, Brücke zum Behandlungsteam (H.1.6 Empathie-Matrix, H.2.3 Aktives Zuhören)`,character:`Jonas`,avatar:`🧔`,context:`Dein enger Freund Jonas ist seit Monaten in Behandlung wegen „meiner Krankheit“; mehr hat er nie gesagt, und du hast nie nachgebohrt. Heute Abend sitzt er in deiner Küche und erzählt, er wolle die Therapie abbrechen und stattdessen eine „Natron-Kur“ aus einem Internetforum machen.`,goal:`Zwinge ihn nicht und lass ihn nicht allein. Bleibe, höre zu, finde heraus, was die Kur ihm gibt, und bring ihn dazu, seine Pläne mit seinem Behandlungsteam zu besprechen.`,bereich:`Gesundheit`,laenge:`lang`,ton:`ernst`,bestehenAb:16,lektion:`Bei hohem Einsatz entscheidet nicht das bessere Argument, sondern ob die Beziehung das Gespräch überlebt. Wer bleibt, das Bedürfnis hinter der Kur benennt (Kontrolle, Hoffnung, gehört werden) und eine Brücke zu den Fachleuten baut, hält die Tür offen; Druck, Heimlichkeit und Rechthaben schließen sie. Ob und wie eine Behandlung geändert wird, entscheidet er mit seinem Behandlungsteam, nicht du und nicht ein Forum.`,toolRef:`H.1.6, H.2.1, H.2.3, H.2.4, G.2.3, G.3.1, G.1.4, D.4.3`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Jonas`,speech:`„Ich muss dir was sagen, aber hör bitte erst mal nur zu. Ich breche die Therapie ab. Ich habe eine Natron-Kur gefunden, da schreiben Leute, die damit ihre Krankheit besiegt haben. Ab Montag mache ich das.“`,options:[{text:`„Jonas, das ist gefährlich! Für Natron gibt es keinen Beleg, dass es eine schwere Krankheit heilt, und das weißt du. Hör auf damit, das lasse ich nicht zu.“`,style:`frontal`,reaction:`„Genau deshalb habe ich es dir nicht früher gesagt. Ihr behandelt mich alle wie ein Kind.“`,feedback:`Frontalangriff plus Verbot: Er fühlt sich entmündigt, und aus dem Thema Krankheit wird ein Machtkampf (H.2.1). Die Sachaussage stimmt, kommt aber als Befehl.`,score:-2,nextStepId:`step-fail`},{text:`„Nein, bitte nicht! Ich ertrage den Gedanken nicht, dich zu verlieren. Versprich mir, dass du das nicht machst, bitte, versprich es mir!“`,style:`affektiv`,reaction:`„Jetzt muss ich auch noch dich trösten. Ich wollte doch nur einmal darüber reden, ohne dass jemand weint.“`,feedback:`Mitpanik: Deine Angst ist echt, aber er muss sie jetzt zusätzlich tragen. Mitgefühl braucht einen ruhigen Anker (H.1.6).`,score:-1,nextStepId:`step-panik`},{text:`„Danke, dass du es mir sagst, ausgerechnet mir. Ich bin erst mal nur da. Was ist passiert, dass du so nicht weitermachen kannst?“`,style:`deeskalierend`,reaction:`„*atmet aus* Ich hatte Angst, du explodierst. Es ist... alles zu viel geworden.“`,feedback:`Beziehung zuerst: Du würdigst das Vertrauen, widersprichst noch nicht und fragst nach dem Auslöser statt nach der Kur (H.2.3 Aktives Zuhören).`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Jonas`,speech:`„Ich bin so müde. Die Nebenwirkungen, die Termine, jeder Befund macht mich kleiner. Und im Forum steht: Die Pharmaindustrie will, dass du Patient bleibst. Natron kostet drei Euro, und ich bin wieder Herr über meinen Körper.“`,options:[{text:`„Für Natron gibt es keinen Beleg, dass es eine schwere Krankheit wie deine heilt. Das ist keine Meinungsfrage, sondern eine Frage der Datenlage.“`,style:`frontal`,reaction:`„Beleg, Beleg. Du klingst genau wie die im Krankenhaus. Ich dachte, du bist auf meiner Seite.“`,feedback:`Der Satz ist sachlich richtig, kommt aber zu früh und ohne Gefühl. Er hört Lehrstoff statt Verbündeten und geht in Deckung.`,score:0,nextStepId:`step-2b`},{text:`„Das klingt nach Monaten voller Kraftakte und nach dem Wunsch, selbst etwas in der Hand zu haben. Was soll die Kur dir geben, das dir fehlt?“`,style:`sokratisch`,reaction:`„*schweigt kurz* Dass ich nicht nur abwarte. Dass ich etwas tue, statt dass etwas mit mir getan wird.“`,feedback:`Du benennst das Bedürfnis hinter dem Mittel: Kontrolle, Handlungsfähigkeit. Die Empathie-Matrix trennt Verstehen von Zustimmung (H.1.6).`,score:3,nextStepId:`step-3`},{text:`„Drei Euro, ja? Klar, und die Pharmaindustrie hat sich die Gegner von Natron bestimmt auch ausgedacht. Gut kombiniert, Sherlock.“`,style:`sarkastisch`,reaction:`„Sehr witzig. Mach dich nur lustig, ich habe schon verstanden.“`,feedback:`Geistreich und verführerisch, aber der Spott trifft den Menschen, nicht die Behauptung. Bei einem Kranken wirkt er wie Verrat.`,score:-2,nextStepId:`step-fail`}]},"step-2b":{id:`step-2b`,speaker:`Jonas`,speech:`„Und warum sind die Leute im Forum dann seit Jahren gesund? Ich kann doch nicht nur auf Ärzte vertrauen, die mich nach zehn Minuten wieder aus dem Zimmer schieben.“`,options:[{text:`„Zehn Minuten sind wirklich knapp, das ärgert mich für dich. Was würdest du fragen, wenn mal jemand ausreichend Zeit für dich hätte?“`,style:`deeskalierend`,reaction:`„*überlegt* Ehrlich? Eine Menge. Ob man gegen die Übelkeit etwas tun kann, zum Beispiel.“`,feedback:`Du gibst ihm recht, wo er recht hat, und holst das Gespräch zu seinen offenen Fragen zurück, statt über das Forum zu streiten.`,score:2,nextStepId:`step-3`},{text:`„Die Leute im Forum kennst du doch gar nicht. Woher willst du wissen, dass es sie überhaupt gibt und dass sie gesund sind?“`,style:`frontal`,reaction:`„Du glaubst also nicht mal, dass es diese Menschen gibt. Na danke.“`,feedback:`Die Frage ist als Falle gebaut. Er spürt das, fühlt sich vorgeführt und verteidigt die Gruppe statt sie zu prüfen.`,score:-2,nextStepId:`step-fail`},{text:`„Vielleicht hast du recht, ich kenne mich damit ja gar nicht aus. Du musst am besten wissen, was gut für dich ist, und ich unterstütze dich.“`,style:`ausstieg`,reaction:`„Danke. Endlich einer, der mich versteht. Dann mache ich ab Montag Ernst.“`,feedback:`Kapitulation, die sich nach Respekt anfühlt: Du lässt ihn mit der Entscheidung allein und gibst jede Chance auf ein Gespräch mit dem Team auf.`,score:-1}]},"step-3":{id:`step-3`,speaker:`Jonas`,speech:`„Es ist mein Körper. Ich lasse mir nicht mehr vorschreiben, was ich damit mache, auch von dir nicht. Die Kur lässt mich endlich selbst handeln.“`,options:[{text:`„Es ist dein Körper, und ich schreibe dir nichts vor. Ich bleibe auch, wenn du anders entscheidest. Wer kennt deine Krankheit am besten?“`,style:`sokratisch`,reaction:`„*zögert* Mein Team, schon. Aber die sehen nur Werte, keinen Menschen.“`,feedback:`Autonomie anerkennen und zugleich Beziehung zusichern entschärft das Freiheitsargument (G.1.4). Die leitende Frage führt ihn selbst zu den Fachleuten.`,score:3,nextStepId:`step-4`},{text:`„Dein Körper, klar. Aber wenn du dich dafür umbringst, sehe ich nicht tatenlos zu. Dann hole ich notfalls deine Familie dazu, damit dich jemand stoppt.“`,style:`frontal`,reaction:`„Du holst meine Familie? Dann hast du mich verraten. Raus mit dir aus meinem Leben.“`,feedback:`Drohung mit Verrat: Wer Druck über Dritte aufbaut, zerstört genau das Vertrauen, das ihn noch erreichen könnte.`,score:-2,nextStepId:`step-fail`},{text:`„Dann tu, was du willst. Aber es bricht mir das Herz, und ich weiß nicht, ob ich das mitansehen kann. Frag mich bitte nicht, es gutzuheißen.“`,style:`affektiv`,reaction:`„Dann ist es wohl besser, wenn ich dich nicht mehr damit belaste. Ich melde mich.“`,feedback:`Ehrlich, aber du machst deine Not zum Preis seiner Entscheidung. Er zieht sich zurück und erzählt dir nichts mehr.`,score:-1}]},"step-4":{id:`step-4`,speaker:`Jonas`,speech:`*schweigt lange* „Weißt du, was das Schlimmste ist? Ich habe Angst. Wenn die Kur nicht klappt, bin ich selbst schuld. Wenn die Therapie nicht klappt, habe ich wenigstens alles versucht. Ich weiß nicht, was von beidem schlimmer ist.“`,options:[{text:`„Danke, dass du mir das anvertraust. Du hast Angst und willst später nichts bereuen. Was würdest du in einem Jahr am wenigsten bereuen?“`,style:`sokratisch`,reaction:`„*leise* Dass ich nicht gefragt habe. Dass ich einfach weggelaufen bin.“`,feedback:`Du spiegelst Angst und Wunsch, ohne zu bewerten, und die Frage lässt ihn selbst den wunden Punkt finden (H.2.3).`,score:3,nextStepId:`step-5`},{text:`„Angst ist normal, aber Entscheidungen aus Angst sind schlechte Entscheidungen. Du solltest in Ruhe und ganz rational abwägen, was dir hilft.“`,style:`frontal`,reaction:`„Rational. Klar. Als hätte ich in den letzten Monaten über nichts anderes nachgedacht. Aber gut, red weiter.“`,feedback:`Gut gemeint, aber belehrend: Gefühle werden zum Denkfehler erklärt. Er bleibt im Gespräch, doch ein Stück distanzierter.`,score:0,nextStepId:`step-5`},{text:`„Ach Jonas, komm her.“ *Umarmung* „Es wird alles gut, ich verspreche es dir. Wir schaffen das gemeinsam, du wirst sehen, am Ende ist alles in Ordnung.“`,style:`affektiv`,reaction:`„*versteift sich kurz* Das kannst du doch gar nicht wissen. Aber danke, dass du es sagst.“`,feedback:`Die Nähe tut gut, das Versprechen nicht: Niemand kann es halten, und er merkt es. Falsche Beruhigung nimmt seine Angst nicht ernst.`,score:-1,nextStepId:`step-5`}]},"step-5":{id:`step-5`,speaker:`Jonas`,speech:`„Mein Team kennt das Forum nicht. Die würden die Augen verdrehen, und ich wäre der Spinner. Dabei habe ich nie gefragt, ob man gegen die Nebenwirkungen etwas tun kann.“`,options:[{text:`„Dann frag genau das: Was hilft gegen die Nebenwirkungen, und was halten sie von der Kur? Ich komme mit ins Wartezimmer.“`,style:`sokratisch`,reaction:`„Du würdest mitkommen? ... Das wäre mir wichtig. Aber was, wenn sie mich abkanzeln?“`,feedback:`Du machst aus Ja oder Nein ein Gespräch: seine Fragen, sein Tempo, du als Begleiter. Die Entscheidung bleibt bei ihm (H.2.4).`,score:3,nextStepId:`step-6`},{text:`„Weißt du was, ich rufe deine Ärztin an und sage ihr, was du vorhast. Dann bist du das Problem los, und sie erklärt dir alles in Ruhe.“`,style:`frontal`,reaction:`„Du gehst hinter meinem Rücken zu meiner Ärztin? Dann sind wir fertig, ich meine es ernst.“`,feedback:`Gut gemeint, aber ein Vertrauensbruch. Er soll selbst gehen und fragen; sonst bestätigst du, dass alle über seinen Kopf hinweg handeln.`,score:-2,nextStepId:`step-fail`},{text:`„Mach doch beides: Therapie weiter und nebenbei die Natron-Kur. Dann hast du dein Gefühl von Kontrolle, und alles ist abgedeckt, ohne Streit.“`,style:`ausstieg`,reaction:`„Beides, genau! Das mache ich. Dann muss ich es den Ärzten ja gar nicht erst sagen.“`,feedback:`Der Kompromiss klingt friedlich, ersetzt aber das Gespräch mit dem Team nicht. Ob sich etwas verträgt, kann nur das Behandlungsteam beurteilen.`,score:-1}]},"step-6":{id:`step-6`,speaker:`Jonas`,speech:`„Und wenn sie mich abkanzeln? Wenn sie sagen, ich bin ein Idiot, dass ich überhaupt darüber nachdenke?“`,options:[{text:`„Dann schreiben wir heute deine drei Fragen auf: Was bringt die Therapie? Was lindert die Nebenwirkungen? Was sagt ihr zur Kur?“`,style:`sokratisch`,reaction:`„*holt einen Zettel* Okay. Drei Fragen. Das schaffe ich vielleicht.“`,feedback:`Konkrete Vorbereitung nimmt der Angst die Schwammigkeit und macht ihn vom Bittsteller zum Fragenden.`,score:3,nextStepId:`step-7`},{text:`„Dann kanzele ich zurück. Ich habe einen Kugelschreiber, ein sehr langes Gedächtnis und im Zweifel eine ziemlich laute Stimme, versprochen.“`,style:`humorvoll`,reaction:`„*lacht kurz* Ein Anwalt mit Kugelschreiber. Gut zu wissen. Aber ich will keinen Krieg.“`,feedback:`Der Humor entlastet und zeigt Loyalität, liefert aber keinen Plan. Außerdem kündigst du Streit an, den er gerade nicht will.`,score:1,nextStepId:`step-7`},{text:`„Die sind Profis, die haben schon alles gehört. Das ist deren Alltag, vor denen musst du wirklich keine Angst haben, glaub mir einfach.“`,style:`deeskalierend`,reaction:`„Vielleicht. Du hast leicht reden, ich bin der, der da sitzt.“`,feedback:`Beruhigung ohne Vorbereitung: Sie nimmt seine Sorge nicht ernst genug, um sie aufzulösen.`,score:0,nextStepId:`step-7`}]},"step-7":{id:`step-7`,speaker:`Jonas`,speech:`*Nachricht, 22:40 Uhr, am Abend vor dem Termin* „Ich glaube, ich sage morgen ab. Vielleicht ist die Kur Quatsch, aber ich wollte noch einmal hoffen dürfen. Das Forum hat mir wenigstens Hoffnung gegeben.“`,options:[{text:`„Hoffnung ist kein Quatsch, und du darfst wackeln. Ich hole dich morgen um acht ab, und danach gibt es Pizza, egal, was herauskommt.“`,style:`deeskalierend`,reaction:`„Pizza. Okay. Das klingt nach etwas, auf das ich mich freuen kann. Um acht, ja?“`,feedback:`Du erlaubst den Zweifel, würdigst die Hoffnung und machst den Weg klein: Abholen, Warten, Pizza. Aus Druck wird Begleitung (H.1.6).`,score:3,nextStepId:`step-8`},{text:`„Du sagst nicht ab. Wir haben das heute besprochen, du hast es versprochen. Morgen um acht stehe ich vor deiner Tür, und du kommst mit.“`,style:`frontal`,reaction:`„Hör auf, mich zu schieben. Ich habe nichts versprochen.“ *Er antwortet nicht mehr.*`,feedback:`Der Zwang schlägt in dem Moment zu, in dem Freiwilligkeit alles ist. Er erlebt wieder, dass andere über ihn bestimmen.`,score:-2},{text:`„Wenn du absagst, ist das deine Entscheidung. Sag mir nur Bescheid, damit ich weiß, woran ich bin, und überleg es dir noch einmal in Ruhe.“`,style:`ausstieg`,reaction:`„Gut. Ich melde mich. Gute Nacht.“ *Er meldet sich nicht.*`,feedback:`Respektvoll, aber du verlässt ihn in der Nacht des Zweifels. Genau jetzt braucht er einen konkreten Anker.`,score:-1}]},"step-8":{id:`step-8`,speaker:`Jonas`,speech:`„Sie haben sich Zeit genommen. Die Ärztin sagt, für Natron gebe es keinen Beleg, dass es meine Krankheit heilt, aber sie hat mich nicht ausgelacht. Wegen der Nebenwirkungen ändern sie etwas. Ich mache die Therapie erst mal weiter. Und ich habe trotzdem Angst.“`,options:[{text:`„Danke, dass du hingegangen bist und gefragt hast. Du hattest Angst und hast trotzdem gehandelt. Ich komme gern zu den nächsten Terminen mit.“`,style:`deeskalierend`,reaction:`„Ich mag. Das würde mir sehr helfen. Danke, dass du nicht gegangen bist.“`,feedback:`Du würdigst sein Handeln statt deines Sieges und bietest weitere Begleitung an. So bleibt das Team ein Ort, an den er mit Fragen zurückkehren kann.`,score:3},{text:`„Siehst du, genau das habe ich dir gesagt. Natron hilft nicht, die Ärztin hat es bestätigt. Ich wusste von Anfang an, wie das ausgeht.“`,style:`frontal`,reaction:`„Ja, ja, du hattest recht. Schön für dich. Ich dachte, es geht heute um mich.“`,feedback:`Rechthaben auf der Zielgeraden: Du machst aus seinem mutigen Schritt deinen Triumph. Zurück bleibt das Gefühl, bewertet zu werden.`,score:-1},{text:`„Pizza bleibt Pizza: Ich bestelle schon, du suchst den Film aus. Und wenn die Angst nachts kommt, schreib mir, auch um drei, ich schlafe sowieso schlecht.“`,style:`humorvoll`,reaction:`„*lacht erleichtert* Abgemacht. Aber keinen Film, in dem jemand stirbt.“`,feedback:`Wärme mit Leichtigkeit: Nähe im Alltag und ein offenes Angebot für die Nächte tragen ihn, ohne dass du die Angst wegredest.`,score:2}]},"step-fail":{id:`step-fail`,speaker:`Jonas`,speech:`„Ich dachte, bei dir kann ich ehrlich sein. Ich glaube, ich gehe jetzt besser.“ *steht auf und nimmt seine Jacke*`,options:[{text:`Szenario beendet: Jonas hat sich zurückgezogen und wird dir nichts mehr erzählen. Die Natron-Kur bleibt sein Geheimnis.`,style:`ausstieg`,reaction:`Wer Druck macht oder spottet, verliert den Zugang. Ohne Vertrauen gibt es keine Brücke zum Behandlungsteam.`,feedback:`Beim nächsten Mal: bleiben, zuhören, das Bedürfnis hinter der Kur finden, erst dann die Fachleute ins Spiel bringen.`,score:0}]},"step-panik":{id:`step-panik`,speaker:`Jonas`,speech:`„Ich wollte Hilfe, keinen Streit. So kann ich nicht über meine Angst sprechen. Ich muss jetzt allein sein.“ *Er verlässt die Küche.*`,options:[{text:`Szenario beendet: Deine Angst hat das Gespräch überlagert, und Jonas trägt jetzt auch noch deine Sorge mit.`,style:`ausstieg`,reaction:`Mitgefühl ohne Halt kippt in Mitleiden. Er braucht jemanden, der ruhig bleibt.`,feedback:`Atme durch, bevor du antwortest, und stelle seine Erfahrung in den Mittelpunkt, nicht deine Angst (H.1.6).`,score:0}]}}},{id:`scen-cousin-drops`,title:`Alex und die Drops`,subtitle:`Brücken statt Mauern, Ausstieg und Schutz vor Isolation (H.1.6, H.2.3, H.2.4)`,character:`Alex`,avatar:`🌙`,context:`Dein Cousin Alex hat im Frühjahr seinen Job verloren. Seitdem verbringt er seine Nächte in der Online-Community „Drops“, wo ein anonymer Absender in Rätseln „enthüllt“, wie die Welt wirklich gelenkt wird. Nachts um kurz vor drei vibriert dein Handy.`,goal:`Halte die Verbindung, bevor die Gruppe es für dich tut. Höre zu, ohne Zustimmung zu heucheln, öffne Zweifel durch Fragen und baue Alex eine Brücke zurück in die Familie.`,bereich:`Familie`,laenge:`lang`,ton:`ernst`,bestehenAb:16,lektion:`Gruppen wie „Drops“ binden nicht über Beweise, sondern über Zugehörigkeit, Bedeutung und das Gefühl, gebraucht zu werden. Wer Alex angreift, bestätigt das Feindbild; wer bleibt, Fragen stellt und Alternativen zur Gruppe anbietet, schützt vor Isolation und lässt Zweifel wachsen. Wird es akut, etwa bei Andeutungen von Selbstverletzung, sind professionelle Hilfe und der Notruf 112 wichtiger als jede Gesprächstaktik.`,toolRef:`H.1.6, H.2.1, H.2.2, H.2.3, H.2.4, G.1.1, G.1.2, D.3.4, D.3.8, B.1, A.3`,startStepId:`step-1`,steps:{"step-1":{id:`step-1`,speaker:`Alex`,speech:`*Nachricht, 2:47 Uhr* „Bist du wach? In einer Stunde kommt der nächste Drop. Es wird endlich alles zusammenpassen. Ich wollte, dass du es als Erster weißt.“`,options:[{text:`„Alex, es ist drei Uhr nachts! Du steckst in einer Sekte, nur weil du seit März keinen Job hast. Hör endlich auf mit dem Quatsch.“`,style:`frontal`,reaction:`„Ich wusste es. Du bist wie alle anderen. Gute Nacht, Schläfer.“`,feedback:`Frontalangriff: Du bestätigst genau die Erzählung der Gruppe, dass die Familie nicht zuhört und ihn verachtet (H.2.1).`,score:-2,nextStepId:`step-fail`},{text:`„Ich bin todmüde, Alex. Schlaf bitte auch mal, wir reden morgen in Ruhe darüber. Okay? Gute Nacht und bis morgen früh.“`,style:`ausstieg`,reaction:`„Morgen. Klar. Schon okay, die anderen sind ja wach.“ *Er schreibt nicht mehr.*`,feedback:`Das Abwimmeln ist menschlich, aber um drei Uhr nachts kommt er zu dir, weil du die Ausnahme bist. Die anderen sind in dem Moment wacher als du.`,score:-1},{text:`„Ich bin wach. Danke, dass du dich ausgerechnet bei mir meldest. Was genau ist ein Drop? Und wie geht es dir gerade damit?“`,style:`deeskalierend`,reaction:`„Echt? Du fragst wirklich? Okay. Warte, ich erkläre es dir.“`,feedback:`Mitfühlende Empathie (H.1.6): Du würdigst das Vertrauen, urteilst nicht und fragst aus Neugier, nicht aus Misstrauen (H.2.3).`,score:3,nextStepId:`step-2`}]},"step-2":{id:`step-2`,speaker:`Alex`,speech:`„Der Absender postet Zahlen und Bilder. Wenn man sie richtig liest, ergeben sie ein Muster, das alles erklärt. Seit ich dabei bin, bin ich nicht mehr der Typ, den sie aussortiert haben. Ich bin einer, der es sieht.“`,options:[{text:`„Dass du dich nach der Kündigung aussortiert fühltest, wusste ich nicht. Was gibt dir die Gruppe, das dir fehlte?“`,style:`sokratisch`,reaction:`„*schreibt lange* Dass jemand wartet, wenn ich schreibe. Dass ich zähle.“`,feedback:`Du erkennst das Bedürfnis hinter dem Glauben: Zugehörigkeit und Bedeutung. Das Verstehen kommt vor jeder Faktenfrage (H.1.6).`,score:3,nextStepId:`step-3`},{text:`„Wer entscheidet eigentlich, welche Zahl ein Zeichen ist und welche Zufall? Genau da beginnt doch das Muster, oder?“`,style:`sokratisch`,reaction:`„Die Community hat Methoden, die du nicht kennst. Aber okay, ich erkläre sie dir. Nicht jetzt.“`,feedback:`Die Frage ist klug, aber zu früh gestellt. Ohne Vertrauensbasis klingt sie wie ein Verhör (H.2.3: erst zuhören).`,score:1,nextStepId:`step-3`},{text:`„Rätselraten mit Fremden um drei Uhr nachts, das ist ja das neue Sudoku. Und? Hat der Absender schon deine Miete bezahlt?“`,style:`sarkastisch`,reaction:`„Sehr witzig. Genau diese Art Spott kenne ich von allen. Gute Nacht.“`,feedback:`Der Spott sitzt, und er trifft den wunden Punkt, den Jobverlust. Alex hört: Man lacht über mich, nicht mit mir.`,score:-2,nextStepId:`step-fail`}]},"step-3":{id:`step-3`,speaker:`Alex`,speech:`„Die hören mir zu. Mama sagt nur: Geh mal an die Luft. Im Chat sagen sie, wer nicht glaubt, zieht dich runter. Vielleicht sollte ich Abstand zu allen halten, die nicht aufwachen wollen.“`,options:[{text:`„Wenn du dich von der Familie abwendest, melde ich mich nicht mehr. Entweder du kommst zur Vernunft, oder wir sind fertig miteinander.“`,style:`frontal`,reaction:`„Siehst du, genau das haben sie vorhergesagt. Danke, dass du es beweist.“`,feedback:`Ein Ultimatum erfüllt die Prophezeiung der Gruppe und treibt ihn in die Isolation, die du verhindern willst.`,score:-2,nextStepId:`step-fail`},{text:`„Ehrlich: Ich glaube nicht an Drops, aber an dich, und ich gehe nicht weg. Warum verlangt ein Ort, der guttut, dass du uns aufgibst?“`,style:`sokratisch`,reaction:`„*Pause* Das hat noch keiner so gefragt. ... Darüber muss ich nachdenken.“`,feedback:`Ehrlichkeit ohne Angriff, Zusicherung der Beziehung und eine Frage zum Isolationsmuster: Gruppen, die Kontaktabbruch verlangen, sollten Verdacht wecken.`,score:3,nextStepId:`step-4`},{text:`„Ich schaue mir die Drops morgen mal an, vielleicht ist ja etwas dran. Hauptsache, wir bleiben im Gespräch, das ist mir am wichtigsten.“`,style:`ausstieg`,reaction:`„Echt?! Ich schicke dir gleich den Einstieg, und ich lade dich in die Gruppe ein. Du wirst es auch sehen!“`,feedback:`Geheuchelte Zustimmung: Du bleibst zwar im Gespräch, aber Alex verbucht dich als Anhänger und zieht dich in die Gruppe statt selbst heraus.`,score:-1}]},"step-4":{id:`step-4`,speaker:`Alex`,speech:`„Du glaubst mir also nicht. Das sagen sie auch: Wer es nicht sehen will, hat Angst vor der Wahrheit.“`,options:[{text:`„Mir geht es nicht ums Glauben, sondern ums Prüfen. Hat ein Drop schon mal etwas vorhergesagt, das wirklich eintraf? Zeig mir das beste Beispiel.“`,style:`sokratisch`,reaction:`„Das beste... *überlegt* Okay, der Tag-X-Drop. Den kennst du noch nicht.“`,feedback:`Du entziehst dich dem Glaubensduell und lädst zum gemeinsamen Prüfen ein. Das umgeht das Klischee „Angst vor der Wahrheit“ (D.3.4).`,score:3,nextStepId:`step-5`},{text:`„Das ist ein klassischer Bestätigungsfehler, Alex: Man merkt sich die Treffer und vergisst die Fehlschläge. Das ist bei jedem Orakel so, auch bei Horoskopen.“`,style:`frontal`,reaction:`„Fachwörter. Du hast für alles eine Schublade. Egal, ich erzähle dir vom besten Drop.“`,feedback:`Fachlich richtig, aber als Vortrag. Alex lässt dich erzählen, öffnet sich dir aber nicht und bleibt auf Verteidigung.`,score:0,nextStepId:`step-5`},{text:`„Ich habe keine Angst vor der Wahrheit, Alex. Ich habe Angst, dass du nachts allein vor dem Bildschirm sitzt und es dir immer schlechter geht.“`,style:`affektiv`,reaction:`„*schreibt langsam* Mir geht's nicht schlecht. Aber okay, ich erzähle dir vom besten Drop.“`,feedback:`Ehrlich und warm, aber sie rückt seine Befindlichkeit in den Vordergrund und lässt die Behauptung unberührt. Gut für die Beziehung, schwach für das Prüfen.`,score:1,nextStepId:`step-5`}]},"step-5":{id:`step-5`,speaker:`Alex`,speech:`„Der Tag-X-Drop: ‚Mitte März ändert sich alles.‘ Ist nichts passiert. Aber der Absender sagt, das war ein Test, wer dranbleibt. Wer geht, hat verloren.“`,options:[{text:`„Da hast du es: Die Vorhersage ist gescheitert, und der Absender deutet sie um. So läuft es bei jeder gescheiterten Prophezeiung, immer dasselbe Spiel!“`,style:`frontal`,reaction:`„Du hörst nicht zu. Er hat es doch erklärt! Ich dachte, du verstehst es.“`,feedback:`Der Triumph über den Widerspruch trifft Alex, nicht den Absender. Der Fehler gehört dem Absender, aber du lässt Alex ihn verteidigen (D.3.8).`,score:-2,nextStepId:`step-fail`},{text:`„Spannend, dass ein Fehlschlag zum Test wird. Nur mal angenommen: Was müsste passieren, damit du sagst, dieser Absender liegt falsch?“`,style:`sokratisch`,reaction:`„*lange Pause* ... Ich weiß nicht. Eigentlich wüsste ich keinen. Das ist komisch, oder?“`,feedback:`Die Falsifizierungsfrage lässt Alex selbst bemerken, dass die Behauptung nicht widerlegbar ist, ohne dass du es sagen musstest (H.2.2).`,score:3,nextStepId:`step-6`},{text:`„Das ist heute Nacht zu viel Stoff. Lass uns schlafen, und morgen schauen wir uns die Drops zusammen bei einem Frühstück an, ja? Ich bringe Brötchen mit.“`,style:`deeskalierend`,reaction:`„Frühstück... okay. Aber der Drop kommt gleich, ich muss ihn lesen.“`,feedback:`Die Deeskalation ist freundlich und baut einen Termin auf, lässt aber den Moment verstreichen, in dem sein Widerspruch offen lag.`,score:1,nextStepId:`step-6`}]},"step-6":{id:`step-6`,speaker:`Alex`,speech:`*lange Pause, dann* „Weißt du, was komisch ist? Ich schlafe kaum noch. Ich habe für den ‚Kreis der Entschlüssler‘ ein Abo abgeschlossen, das ich mir eigentlich nicht leisten kann. Manchmal frage ich mich, ob ... nein, vergiss es.“`,options:[{text:`„Sag es ruhig zu Ende, ich höre zu. Zweifel ist kein Verrat, Alex, das ist Denken. Was würde dir helfen, wieder durchzuschlafen?“`,style:`deeskalierend`,reaction:`„*schreibt* Ich frage mich, ob ich da gerade jemandem Geld und Zeit schenke, der mich gar nicht kennt.“`,feedback:`Du schaffst Sicherheit für den Zweifel. Den Satz muss Alex selbst zu Ende sprechen, damit er seiner ist (H.1.6).`,score:3,nextStepId:`step-7`},{text:`„Siehst du? Du zahlst Geld für Rätsel, die dich um den Schlaf bringen. Das ist Abzocke, und du weißt es. Kündige das Abo sofort!“`,style:`frontal`,reaction:`„Ich habe nichts gesagt. Vergiss alles, was ich geschrieben habe.“ *Er schreibt nicht mehr.*`,feedback:`Du packst den Zweifel sofort als Beute. Wer ihn so verwertet, bringt Alex dazu, ihn nie wieder zu äußern, aus Scham.`,score:-2,nextStepId:`step-fail`},{text:`„Dann lass das Abo doch langsam auslaufen und schlaf erst mal. Du hast in der Zeit bestimmt viel gelernt, das nimmt dir keiner mehr.“`,style:`deeskalierend`,reaction:`„Ja ... vielleicht. Gelernt habe ich schon was. Nur nicht, wie ich ohne die anderen auskomme.“`,feedback:`Freundlich und entlastend, aber der Rat kommt, bevor Alex den Gedanken ausgesprochen hat. Er bringt die Angst vor der Leere selbst an.`,score:0,nextStepId:`step-7`}]},"step-7":{id:`step-7`,speaker:`Alex`,speech:`„Aber wenn ich rausgehe, habe ich niemanden mehr. Das sind meine Leute. Die schreiben mir um drei Uhr nachts zurück, du schläfst ja um die Zeit normalerweise.“`,options:[{text:`„Ich bin gerade wach, wie du siehst. Du musst nichts aufgeben, um uns zu behalten. Wie wäre Samstag im Garten, ohne Drops?“`,style:`deeskalierend`,reaction:`„Samstag ... Garten ... Ohne dass jemand über die Drops diskutiert? Das klingt tatsächlich gut.“`,feedback:`Die Brücke: ein konkretes, niedrigschwelliges Angebot ohne Bedingung. Zugehörigkeit außerhalb der Gruppe ist der wirksamste Schutz (H.2.4).`,score:3,nextStepId:`step-8`},{text:`„Dann lösche heute Nacht alle Chats und die App, ich bleibe am Telefon. Ganz oder gar nicht, Alex, etwas anderes gibt es nicht.“`,style:`frontal`,reaction:`„Das ist, als würdest du meine Familie löschen. Ich kann das nicht. Lass mich in Ruhe.“`,feedback:`Der Ausstieg unter Druck wirkt wie ein Entzug der letzten Freunde. Ein Abbruch ohne neues Netz lässt eine Lücke, die die Gruppe sofort füllt.`,score:-1},{text:`„Es gibt Beratungsstellen für Menschen, die aus solchen Gruppen aussteigen wollen. Ich suche dir eine Nummer raus, wenn du so weit bist.“`,style:`ausstieg`,reaction:`„Beratungsstelle? Ich bin doch nicht krank. ... Aber gut, schick sie mir irgendwann.“`,feedback:`Der Hinweis gehört in den Werkzeugkasten, aber hier fehlt dem Angebot noch das Gefühl, nicht allein zu sein; er hört: Du bist ein Fall. Bei Gedanken, sich etwas anzutun, gilt etwas anderes: nicht allein lassen, Notruf 112 oder Telefonseelsorge 0800 111 0 111.`,score:1,nextStepId:`step-8`}]},"step-8":{id:`step-8`,speaker:`Alex`,speech:`„Okay, Samstag. Aber ich schaue den Kanal trotzdem noch. Ist das in Ordnung für dich?“`,options:[{text:`„Ja, das ist in Ordnung. Ich nehme dir nichts weg, ich möchte nur einen Platz in deinem Leben behalten. Erzähl mir am Samstag davon.“`,style:`deeskalierend`,reaction:`„Danke. Ich glaube, ich hatte gehofft, dass du das sagst. Bis Samstag.“`,feedback:`Du forderst keinen Bruch, sondern bleibst als Alternative erreichbar. Der Ausstieg ist ein Weg, und er gehört Alex.`,score:3},{text:`„Nur wenn du die App löschst, komme ich zum Grillen, sonst wird das nichts. Also: Du entscheidest dich jetzt, die Drops oder wir.“`,style:`frontal`,reaction:`„Dann bleibe ich lieber hier. Da stellt wenigstens keiner Bedingungen.“`,feedback:`Eine Bedingung im letzten Moment macht aus der Brücke wieder eine Mauer und bestätigt Alex genau das, wovor er Angst hat.`,score:-2},{text:`„Der Kanal kann warten, Tante Rosis Kartoffelsalat nicht. Das ist die einzige Verschwörung, die ich unterstütze: Wer zu spät kommt, kriegt nur noch Gurken.“`,style:`humorvoll`,reaction:`„*lacht* Der Kartoffelsalat. Okay, okay, ich komme. Und ich bringe die Gurken mit.“`,feedback:`Verbindender Humor: Er lacht mit, der Samstag wird zur Einladung statt zur Prüfung. Das ersetzt das Gespräch nicht, hält aber die Tür offen.`,score:2}]},"step-fail":{id:`step-fail`,speaker:`Alex`,speech:`„Ich glaube, ich verstehe jetzt, was sie meinen. Gute Nacht.“ *Der Chat ist offline.*`,options:[{text:`Szenario beendet: Alex hat sich zurückgezogen und ist für dich nicht mehr erreichbar. Die Gruppe ist jetzt sein einziger Gesprächspartner.`,style:`ausstieg`,reaction:`Wer angreift oder spottet, bestätigt das Feindbild. Je weniger Außenkontakt, desto stärker die Bindung an die Gruppe.`,feedback:`Beim nächsten Mal: zuerst zuhören, das Bedürfnis hinter dem Glauben finden, dann erst vorsichtig fragen (H.1.6, H.2.3).`,score:0}]}}}];export{e as t};